const areas = [
 {id:'hsq-betriebliches-management', name:'Betriebliches Management', paragraph:1, items:[
 ['planungsprozess','Eine Maschinenbaufirma plant einen zweiten Schichtbetrieb. Nachfrageprognose und verfügbare Fachkräfte widersprechen sich. Welcher nächste Schritt ist für die Planung am tragfähigsten?','Kapazitätsbedarf, Nachfrageannahmen und Personalverfügbarkeit in Szenarien gegenüberstellen.',['Die Schicht sofort starten, weil der Umsatzplan steigt.','Die Personalengpässe aus dem Plan entfernen.','Erst nach Ablauf des Jahres die Nachfrage bewerten.'],'Szenarien machen die Abhängigkeit zwischen Absatzchance und realisierbarer Kapazität sichtbar.','Die Geschäftsleitung kann Überstunden- und Lieferausfallrisiken vor einer Investitions- oder Einstellungsentscheidung abschätzen.'],
 ['planungsprozess','Ein Unternehmen verfehlt zum dritten Mal den Liefertermin für Sonderteile. Welche Planungsänderung adressiert die Ursache am ehesten?','Beschaffungsdurchlaufzeiten und Unsicherheit in die Terminplanung aufnehmen.',['Den Kunden vorsorglich längere Lieferzeiten nennen, ohne Abläufe zu prüfen.','Den Fertigungsplan unverändert lassen und mehr Aufträge annehmen.','Die verspäteten Aufträge aus der Kennzahl entfernen.'],'Die Lieferplanung muss die vorgelagerten Materialzeiten berücksichtigen, damit Termine realistisch werden.','Weniger unrealistische Zusagen senken Nacharbeit in der Planung und stärken die Termintreue.'],
 ['planungsprozess','Die Geschäftsleitung erstellt für das nächste Jahr einen Absatzplan, obwohl ein Hauptkunde seinen Bedarf noch nicht bestätigt hat. Wie sollte die Annahme behandelt werden?','Den Plan mit klar gekennzeichneten Annahmen und Alternativszenarien erstellen.',['Den unbestätigten Bedarf als sicheren Auftrag buchen.','Den Hauptkunden vollständig aus jeder Planung ausschließen.','Die Planungsunsicherheit durch einen pauschalen Umsatzaufschlag verdecken.'],'Sichtbare Annahmen machen den Plan revidierbar, sobald bessere Informationen vorliegen.','Die Liquiditäts- und Personalplanung kann auf Nachfrageänderungen reagieren, statt auf Scheinsicherheit zu beruhen.'],
 ['planungsprozess','Ein Betrieb will den Auftragseingang steigern, doch seine CNC-Auslastung liegt bereits nahe der Grenze. Welche Planung verbindet Absatz und Leistungserstellung?','Absatz- und Kapazitätsplan gemeinsam abstimmen und Engpassalternativen bewerten.',['Den Vertrieb ausschließlich nach Anfragezahl vergüten.','Zusätzliche Aufträge unabhängig vom Liefertermin annehmen.','Die Fertigungskapazität im Plan als unbegrenzt ansetzen.'],'Absatzplanung ist nur erfüllbar, wenn verfügbare Maschinen- und Personalzeit mitbetrachtet werden.','Das Unternehmen kann profitable Aufträge auswählen, ohne eine unhaltbare Lieferpipeline aufzubauen.'],
 ['planungsprozess','Ein Materialpreis wird voraussichtlich stark steigen. Welche Planungsreaktion erlaubt eine robuste Entscheidung?','Auswirkungen auf Bedarf, Bestand, Liquidität und Angebotspreise in Varianten durchrechnen.',['Den Einkaufspreis dauerhaft auf dem aktuellen Stand einfrieren.','Unabhängig vom Bedarf sofort den gesamten Jahresverbrauch kaufen.','Die Preisänderung ausschließlich im Marketingplan behandeln.'],'Varianten zeigen, welche Kombination aus Beschaffung und Preisweitergabe tragbar ist.','Finanzbedarf und Angebotsmarge werden vor der Bindung von Kapital transparenter.'],
 ['statistik','Die Reklamationsquote steigt, während die absolute Zahl der Reklamationen gleich bleibt und die Auslieferungsmenge sinkt. Welche Deutung ist richtig?','Die Quote kann wegen des kleineren Bezugswerts steigen; absolute Werte und Bezugsgröße gemeinsam prüfen.',['Eine steigende Quote beweist, dass mehr Fehler aufgetreten sind.','Die Quote ist mit der Auslieferungsmenge nicht verbunden.','Die Reklamationen sollten aus der Statistik entfernt werden.'],'Eine relative Kennzahl kann sich durch Zähler oder Nenner verändern.','Die Leitung vermeidet eine falsche Ursachenmaßnahme und untersucht die Fehler je gelieferter Einheit.'],
 ['statistik','Die Geschäftsführung vergleicht Krankenstände zweier Monate mit unterschiedlicher Beschäftigtenzahl. Welche Kennzahl ist für den Vergleich geeigneter?','Eine einheitlich definierte Fehlzeitenquote mit vergleichbarer Bezugsgröße berechnen.',['Nur die absolute Zahl der Fehltage vergleichen.','Monatswerte addieren, ohne Beschäftigtenzahl zu berücksichtigen.','Fehlzeiten nachträglich den Urlaubstagen zuschlagen.'],'Eine vergleichbare Quote berücksichtigt die unterschiedliche Größe der Belegschaft.','Personalentscheidungen stützen sich weniger auf Verzerrungen durch unterschiedliche Beschäftigtenzahlen.'],
 ['statistik','Ein Monatsbericht zeigt, dass der durchschnittliche Auftragswert gestiegen ist. Gleichzeitig gibt es weniger Aufträge. Welche Ergänzung hilft bei der Interpretation?','Auftragszahl, Gesamtumsatz und Auftragsmix zusätzlich betrachten.',['Den Mittelwert als Beweis für höheres Gesamtgeschäft werten.','Nur den größten Auftrag für den Vergleich verwenden.','Die Zahl der Aufträge aus dem Bericht entfernen.'],'Der Mittelwert allein sagt nichts darüber, wie sich Gesamtvolumen und Zusammensetzung verändert haben.','Vertriebs- und Kapazitätsplanung erhalten ein vollständigeres Bild der Nachfrage.'],
 ['statistik','Die Liefertermintreue liegt im Quartal bei 92 Prozent. Die Geschäftsleitung möchte wissen, ob sich der Prozess verbessert hat. Was sollte verglichen werden?','Mehrere vergleichbare Perioden und die Definition des zugesagten Termins heranziehen.',['Nur den besten Monat mit dem Quartalswert vergleichen.','Die Kennzahl um verspätete Aufträge bereinigen.','Liefertermintreue mit Umsatzhöhe gleichsetzen.'],'Trend und einheitliche Messdefinition sind nötig, um eine Veränderung belastbar zu beurteilen.','Das Team kann erkennen, ob Maßnahmen dauerhaft wirken oder nur ein einzelner Monat günstig war.'],
 ['statistik','Eine Auswertung weist ungewöhnlich lange Durchlaufzeiten für wenige Aufträge aus. Wie sollte der Mittelwert ergänzt werden?','Verteilung und Ausreißer prüfen und zusätzlich Median oder Häufigkeiten betrachten.',['Den längsten Auftrag aus allen Auswertungen löschen.','Nur den Mittelwert ohne Fallzahlen veröffentlichen.','Die Bearbeitungszeiten pauschal runden.'],'Eine Verteilung zeigt, ob wenige Extremfälle den Mittelwert prägen.','Engpassaufträge werden sichtbar, ohne den Normalfall oder Ausnahmen zu verschleiern.'],
 ['organisation','Angebote bleiben liegen, weil Vertrieb und Kalkulation nicht wissen, wer die technische Prüfung anstößt. Welche Organisationsmaßnahme ist passend?','Schnittstellen, Auslöser und Verantwortlichkeit im Angebotsprozess festlegen.',['Eine zusätzliche Freigabestufe ohne Zuständigkeit schaffen.','Die Aufgabe beiden Bereichen gleichzeitig und ohne Abstimmung übertragen.','Die technische Prüfung aus dem Prozess streichen.'],'Ein definierter Prozessübergang verhindert, dass die Aufgabe zwischen Bereichen verloren geht.','Angebote können zügiger und mit nachvollziehbarer technischer Prüfung erstellt werden.'],
 ['organisation','Die Geschäftsführung möchte Entscheidungen beschleunigen, aber jede Kleinigkeit muss von ihr freigegeben werden. Was ist eine sinnvolle Lösung?','Entscheidungsspielräume nach Betrag oder Risiko delegieren und Eskalationsgrenzen bestimmen.',['Alle Kontrollen ersatzlos abschaffen.','Jede Entscheidung zusätzlich an die Geschäftsführung melden.','Befugnisse informell vergeben, ohne sie mitzuteilen.'],'Abgegrenzte Befugnisse entlasten die Leitung und erhalten Kontrollen bei relevanten Risiken.','Routinefälle werden schneller bearbeitet; wesentliche Verpflichtungen bleiben eskalierbar.'],
 ['organisation','Eine Werkstatt wächst, und Mitarbeitende erhalten widersprüchliche Prioritäten von zwei Vorgesetzten. Was sollte geklärt werden?','Weisungswege und Priorisierungsverantwortung für die betroffenen Aufgaben festlegen.',['Eine dritte Weisungsebene ergänzen.','Mitarbeitende selbst für jeden Zielkonflikt haftbar machen.','Prioritäten täglich ohne Abstimmung wechseln.'],'Eindeutige Weisungswege reduzieren Doppelarbeit und widersprüchliche Arbeitsaufträge.','Die Beschäftigten können ihre Zeit besser auf verbindliche Auftragsziele ausrichten.'],
 ['organisation','Ein Betrieb führt eine neue Software ein, aber niemand ist für Stammdatenqualität zuständig. Welche organisatorische Lücke besteht?','Verantwortung und Pflegeprozess für die Daten festlegen.',['Die Software durch mehr Tabellen ergänzen.','Datenfehler ausschließlich beim Anbieter verorten.','Stammdaten ohne Prüfregeln allen Nutzenden überlassen.'],'Technische Werkzeuge ersetzen keine klare Datenverantwortung.','Verlässliche Stammdaten reduzieren Planungsfehler und falsche Auswertungen.'],
 ['organisation','Im Urlaub einer Schlüsselperson kann niemand Lieferantenbestellungen freigeben. Welche organisatorische Vorsorge ist angemessen?','Vertretung, Zugriff und Übergabe für kritische Aufgaben verbindlich regeln.',['Bestellungen während des Urlaubs grundsätzlich aussetzen.','Zugänge informell weitergeben.','Die Aufgabe ohne Berechtigung jeder Person öffnen.'],'Eine geregelte Vertretung erhält Handlungsfähigkeit und kontrollierten Zugriff.','Materialversorgung bleibt gesichert, ohne interne Kontrollen zu umgehen.'],
 ['personalentwicklung','Neue Messgeräte werden eingeführt; nur zwei Beschäftigte kennen deren Bedienung. Welche Personalentwicklungsmaßnahme reduziert die Abhängigkeit?','Weitere Mitarbeitende bedarfsgerecht qualifizieren und praktische Anwendung nachhalten.',['Die Messgeräte nur von den zwei bisherigen Fachkräften bedienen lassen.','Eine allgemeine Schulung ohne Bezug zum Gerät buchen.','Die Bedienungsanleitung als Qualifikationsnachweis behandeln.'],'Gezielte Qualifizierung baut die Kompetenzlücke auf und Transferkontrolle prüft die Anwendung.','Ausfälle einzelner Schlüsselpersonen blockieren die Qualitätsprüfung weniger leicht.'],
 ['personalentwicklung','Ein Mitarbeiter möchte eine anspruchsvollere Aufgabe übernehmen, zeigt aber noch Unsicherheit bei der Dokumentation. Wie sollte die Führungskraft fördern?','Lernziel, Übungsaufgaben und begleitendes Feedback vereinbaren.',['Die Aufgabe sofort vollständig übertragen und Unterstützung verweigern.','Entwicklung ablehnen, ohne Kompetenzbedarf zu klären.','Nur die Fehlerquote bewerten und kein Lernziel nennen.'],'Ein abgestufter Entwicklungsplan verbindet Herausforderung und notwendige Unterstützung.','Der Betrieb kann Kompetenzen schrittweise erweitern und Qualitätsrisiken begrenzen.'],
 ['personalentwicklung','Nach einer Schulung ändern sich die Fehlerzahlen nicht. Was sollte die Leitung prüfen, bevor sie weitere Kurse bucht?','Ob Lerninhalte angewendet werden können und Arbeitsbedingungen den Transfer erlauben.',['Die Schulung automatisch als wirkungslos einstufen.','Alle Beschäftigten unabhängig von Bedarf erneut anmelden.','Die Fehlerzahlen als Lernnachweis verwenden.'],'Lernerfolg hängt auch von Gelegenheit, Prozess und Unterstützung am Arbeitsplatz ab.','Weiterbildungsbudget kann gezielter eingesetzt und Prozesshindernisse können behoben werden.'],
 ['personalentwicklung','Ein Betrieb verliert wiederholt Wissen, wenn erfahrene Beschäftigte ausscheiden. Welche Maßnahme unterstützt Wissensmanagement?','Kritisches Erfahrungswissen strukturiert dokumentieren und Übergaben organisieren.',['Wissen ausschließlich bei einzelnen Personen belassen.','Alle Arbeitsanweisungen ohne Prüfung veröffentlichen.','Nur die Dauer der Betriebszugehörigkeit erfassen.'],'Dokumentation und Austausch machen wichtiges Wissen für Nachfolge und Einarbeitung nutzbar.','Produktionsabläufe hängen weniger von individuellem Gedächtnis ab.'],
 ['personalentwicklung','Eine neue Fachkraft soll eingearbeitet werden, aber jede Schicht erklärt die Abläufe anders. Was hilft?','Einen abgestimmten Einarbeitungsplan mit Lernschritten und Ansprechpersonen erstellen.',['Die Fachkraft ohne Einweisung sofort allein einsetzen.','Alle Details ausschließlich mündlich weitergeben.','Die Einarbeitung nach dem ersten Arbeitstag beenden.'],'Ein strukturierter Plan schafft eine konsistente Lernfolge und erkennbare Verantwortlichkeit.','Die neue Person erreicht schneller einen verlässlichen Arbeitsstand und verursacht weniger vermeidbare Fehler.'],
 ['entscheidungstechnik','Zwei Lieferanten bieten vergleichbare Qualität, aber unterschiedliche Preise und Lieferzeiten. Wie lässt sich die Auswahl nachvollziehbar machen?','Kriterien gewichten und Angebote anhand derselben Bewertungsmaßstäbe vergleichen.',['Den günstigsten Preis automatisch als bestes Angebot wählen.','Nach persönlicher Bekanntheit entscheiden, ohne Kriterien festzulegen.','Preise und Lieferzeiten addieren, ohne Bedeutung festzulegen.'],'Ein gewichteter Kriterienvergleich macht Zielprioritäten und Abwägungen transparent.','Die Beschaffungsentscheidung lässt sich gegenüber Leitung und Produktion begründen.'],
 ['entscheidungstechnik','Ein Team diskutiert lange über Ursachen eines Maschinenstillstands, obwohl die wichtigsten Fakten fehlen. Welche Technik bringt die Entscheidung voran?','Fehlende Informationen, Hypothesen und Prüfschritte getrennt erfassen.',['Die erste Vermutung als Ursache festschreiben.','Mehrheitsabstimmung über ungeprüfte Ursachen durchführen.','Die Diskussion abbrechen und denselben Ablauf wiederholen.'],'Die Trennung von Fakten und Annahmen lenkt die Analyse auf überprüfbare Ursachen.','Die Instandhaltung kann wirksamer priorisieren und wiederholte Stillstände vermeiden.'],
 ['zeitmanagement','Eine Führungskraft bearbeitet ständig dringende Rückfragen und verschiebt wichtige Personalplanung. Welche Methode hilft bei der Priorisierung?','Aufgaben nach Wichtigkeit und Dringlichkeit ordnen und Zeitblöcke für wichtige Arbeit schützen.',['Jede eingehende Anfrage sofort unterbrechen lassen.','Nur die kürzesten Aufgaben bearbeiten.','Alle Aufgaben gleichzeitig beginnen.'],'Priorisierung schützt wichtige, nicht unmittelbar dringende Führungsaufgaben vor dauerhaftem Aufschub.','Personalengpässe werden vorausschauender bearbeitet statt erst im Krisenmodus.'],
 ['kreativitaet','Ein Betrieb sucht Ideen zur Verringerung von Rüstzeiten; in Besprechungen sprechen meist dieselben Personen. Welche Moderation ist hilfreich?','Zunächst Ideen unabhängig sammeln und danach gemeinsam anhand vereinbarter Kriterien bewerten.',['Jede Idee während der Sammlung sofort kritisieren.','Die erste Idee ohne Vergleich übernehmen.','Nur Führungskräfte Vorschläge entwickeln lassen.'],'Getrennte Ideen- und Bewertungsphasen verringern vorschnelle Ablehnung und erweitern Beteiligung.','Mehr praktikable Verbesserungsoptionen können geprüft werden, bevor Ressourcen gebunden werden.'],
 ['wissensmanagement','Eine aktualisierte Arbeitsanweisung wird in einem persönlichen Ordner gespeichert und erreicht die Schichten nicht. Was ist die passende Verbesserung?','Eine zugängliche, versionierte Ablage mit Verantwortlichkeit für Veröffentlichung einrichten.',['Mehrere unkontrollierte Kopien per E-Mail verteilen.','Alte Fassungen im Umlauf lassen, um Auswahl zu ermöglichen.','Die Änderung nur in einer Besprechung erwähnen.'],'Eine gelenkte Version stellt sicher, dass Mitarbeitende dieselbe gültige Information nutzen.','Fehler durch veraltete Arbeitsweisen und widersprüchliche Dokumente werden seltener.']
 ]}
];
areas[0].items.push(
 ['decisiontechnique','Ein Investitionsgremium bewertet eine neue Drehmaschine; die Mitglieder verwenden unterschiedliche Annahmen zu Auslastung und Nutzungsdauer. Wie wird der Vergleich belastbar?','Gemeinsame Annahmen und einen einheitlichen Betrachtungszeitraum festlegen, dann neu vergleichen.',['Die Bewertungen mitteln, obwohl sie verschiedene Nutzungsdauern enthalten.','Nur die höchste Einzelbewertung übernehmen.','Die Annahmen nachträglich so ändern, dass die bevorzugte Anlage gewinnt.'],'Unterschiedliche Rechengrundlagen machen Alternativen nicht vergleichbar.','Die Leitung erhält eine nachvollziehbare Entscheidungsgrundlage statt eines scheinbar präzisen, aber verzerrten Rankings.'],
    ['analyse','Der Auftragseingang steigt, zugleich sinkt der Deckungsbeitrag je Auftrag. Welche Auswertung zeigt, ob sich der Deckungsbeitrag je Segment durch veränderten Auftragsmix oder niedrigere Verkaufspreise verändert hat?','Auftragsmix, Preisnachlässe und variable Kosten nach Segment untersuchen.',['Auftragseingang nach Stückzahl aufschlüsseln und die durchschnittliche Marge als Maßstab für alle Segmente verwenden.','Nur die Gesamtkosten betrachten und die Erlösseite ignorieren.','Personalaufwand je Auftrag auf Veränderungen prüfen und Preis- sowie Materialeffekte anschließend nach Produktgruppe vergleichen.'],'Mehr Volumen kann aus margenschwachen Aufträgen stammen; die Zusammensetzung muss geprüft werden.','Der Vertrieb kann seine Angebotsstrategie an profitablen Segmenten ausrichten.'],
 ['risikomanagement','Ein Mitarbeiter kennt allein den Zugang zum Prüfmittelarchiv. Welche Maßnahme verbessert die betriebliche Resilienz?','Zugriff und Vertretungswissen für berechtigte Personen kontrolliert aufbauen.',['Das Passwort unkontrolliert an alle Beschäftigten verteilen.','Den Zugang aus Sicherheitsgründen dauerhaft sperren.','Die Abhängigkeit bis zum Ausfall nicht dokumentieren.'],'Kontrollierte Vertretung verringert Ausfallabhängigkeit und erhält angemessene Zugriffssteuerung.','Qualitätsnachweise bleiben auch bei Abwesenheit verfügbar.'],
 ['zielsystem','Die Fertigung wird nach Auslastung bewertet und produziert dadurch Teile ohne kurzfristigen Bedarf. Welche Steuerungsänderung ist sinnvoll?','Auslastung mit Bestand, Lieferfähigkeit und tatsächlichem Bedarf gemeinsam bewerten.',['Auslastung als einziges Leistungsziel beibehalten.','Zusätzliche Produktion grundsätzlich als Verkaufserfolg verbuchen.','Bestände aus der Zielbewertung ausschließen.'],'Einzelkennzahlen können unerwünschte Anreize setzen; ergänzende Ziele zeigen Nebenwirkungen.','Unnötige Lagerbestände und gebundenes Kapital können sinken, ohne die Lieferfähigkeit zu vernachlässigen.'],
 ['zielsystem','Ein Vertriebsziel belohnt nur den Umsatz; Mitarbeitende geben regelmäßig hohe Rabatte. Welche Anpassung adressiert den Fehlanreiz?','Umsatzziel um Margen- und Qualitätskriterien ergänzen.',['Umsatzziel erhöhen, ohne Nachlassverhalten zu prüfen.','Rabatte nachträglich als Marketingumsatz verbuchen.','Die Wirkung des Ziels erst nach mehreren Jahren beurteilen.'],'Einseitige Umsatzanreize können Erlös auf Kosten der Marge fördern.','Angebote werden stärker auf tragfähige Aufträge und Kundennutzen ausgerichtet.'],
 ['organisation','Kundenreklamationen werden an den Vertrieb gemeldet, aber nicht an Qualität oder Fertigung weitergegeben. Welche Struktur ist erforderlich?','Einen verbindlichen Reklamationsprozess mit Weiterleitung, Verantwortlichen und Rückmeldung einrichten.',['Reklamationen ausschließlich im Vertrieb archivieren.','Jede Abteilung eigene, nicht abgestimmte Listen führen lassen.','Rückmeldungen an den Kunden vor Ursachenprüfung endgültig schließen.'],'Ein klarer Informationsweg verbindet Kundensignal, Ursachenbearbeitung und Korrektur.','Wiederkehrende Fehler werden eher systemisch behoben und Kunden erhalten verlässlichere Antworten.'],
 ['wissensmanagement','Eine wichtige Prozessänderung wird nur in einer Chatnachricht festgehalten, die später nicht auffindbar ist. Wie sollte Wissen gesichert werden?','Die freigegebene Änderung in der gelenkten Prozessdokumentation mit Datum und Version ablegen.',['Die Nachricht mit immer neuen Antworten verlängern.','Die Änderung als Erfahrungswissen der schreibenden Person belassen.','Alle Chatverläufe ohne Ordnung exportieren.'],'Nachvollziehbare Ablage und Versionierung machen Prozesswissen dauerhaft auffindbar.','Schichtteams können den aktuellen Standard konsistent anwenden.'],
 ['zeitmanagement','Eine Projektleitung erhält viele parallele Aufgaben; mehrere Abhängigkeiten blockieren Folgearbeiten. Welche Planungshilfe ist angemessen?','Arbeitspakete, Abhängigkeiten, Verantwortliche und kritischen Zeitpfad sichtbar planen.',['Alle Aufgaben mit identischer Dauer parallel terminieren.','Nur ein Enddatum kommunizieren.','Die Abhängigkeiten den Mitarbeitenden zur spontanen Lösung überlassen.'],'Abhängigkeiten bestimmen, welche Verzögerungen den Endtermin tatsächlich gefährden.','Ressourcen können auf zeitkritische Schritte konzentriert und Verzögerungen früh eskaliert werden.'],
 ['projektmoderation','Bei einem bereichsübergreifenden Projekt reden Fertigung und Vertrieb aneinander vorbei. Welche Moderationsfrage hilft, das gemeinsame Ziel zu klären?','Welche messbare Veränderung soll der Kunde nach Umsetzung wahrnehmen?',['Welcher Bereich hat in der Vergangenheit am häufigsten Fehler gemacht?','Wer kann das Projekt ohne weitere Abstimmung freigeben?','Wie lässt sich die Besprechung möglichst schnell beenden?'],'Eine gemeinsame Kundensicht richtet unterschiedliche Fachperspektiven auf ein überprüfbares Projektergebnis aus.','Der Projektumfang wird stärker am Nutzen ausgerichtet und Bereichskonflikte werden sachlicher verhandelbar.'],
 ['statistik','Die Ausschussquote eines Produkts steigt nach einer Änderung des Prüfverfahrens. Was ist vor einem Ursachenurteil zu prüfen?','Ob Definition, Stichprobe und Erfassungsmethode vor und nach der Änderung vergleichbar sind.',['Die neue Quote als Beweis für eine schlechtere Fertigung werten.','Die alte Messreihe löschen, weil das Verfahren geändert wurde.','Nur die Zahl geprüfter Teile betrachten.'],'Ein Methodenwechsel kann eine Kennzahlenänderung verursachen, ohne dass sich die Prozessqualität verändert hat.','Die Leitung vermeidet unnötige Prozessänderungen und trennt Mess- von Fertigungseffekten.'],
 ['analyse','Ein Unternehmen verfügt über hohe Auslastung, aber niedrige Kundenzufriedenheit. Welche Analyse verbindet Prozess- und Marktsicht?','Lieferzeiten und Qualitätsdaten mit Kundenrückmeldungen sowie Prozessursachen verknüpfen.',['Auslastung als ausreichenden Erfolgsnachweis verwenden.','Kundenfeedback nur nach Umsatzhöhe sortieren.','Die Produktionsmenge erhöhen, um die Zufriedenheit zu verbessern.'],'Hohe Auslastung erklärt nicht, ob Kunden ihre vereinbarte Leistung erhalten.','Verbesserungen können an tatsächlichen Termintreue- oder Qualitätsproblemen ansetzen.'],
 ['personalentwicklung','Ein erfahrener Beschäftigter soll eine neue Teamleitungsaufgabe übernehmen, hat aber wenig Erfahrung mit Mitarbeitergesprächen. Was ist eine geeignete Förderung?','Gesprächskompetenz gezielt entwickeln und die ersten Gespräche reflektiert begleiten.',['Die Beförderung wegen fehlender Routine grundsätzlich ausschließen.','Alle schwierigen Personalgespräche an die Geschäftsführung abgeben.','Die neue Rolle ohne Vorbereitung beginnen lassen.'],'Die Entwicklungsmaßnahme schließt eine rollenspezifische Kompetenzlücke und bietet Transferunterstützung.','Die neue Leitung kann Konflikte und Leistungsthemen früher konstruktiv bearbeiten.'],
 ['entscheidungstechnik','Ein Team muss zwischen Eigenfertigung und Fremdbezug entscheiden; mehrere Kriterien sind nicht in Geld messbar. Welche Methode passt?','Nutzwertanalyse mit transparenten Kriterien, Gewichtungen und Sensitivitätsprüfung verwenden.',['Nur den Einkaufspreis vergleichen.','Alle Kriterien gleichsetzen, ohne ihre Bedeutung zu diskutieren.','Die nicht-monetären Kriterien aus der Entscheidung entfernen.'],'Eine Nutzwertanalyse kann qualitative Kriterien strukturiert einbeziehen; Gewichte bleiben prüfbare Annahmen.','Die Entscheidung berücksichtigt neben Kosten auch Qualität, Abhängigkeit und Know-how.'],
 ['organisation','Ein Unternehmen hat keinen klaren Eskalationsweg, wenn ein Lieferant eine kritische Zusage nicht einhält. Welche Organisationsregel hilft?','Auslöser, zuständige Rolle und Eskalationsstufe für kritische Lieferabweichungen bestimmen.',['Jede Person soll parallel beim Lieferanten reklamieren.','Eskalation erst nach Produktionsstillstand zulassen.','Lieferabweichungen ausschließlich in der Jahresbewertung behandeln.'],'Ein definierter Eskalationsweg ermöglicht rechtzeitige koordinierte Reaktion.','Engpässe können früher mit Einkauf und Fertigung bearbeitet werden.'],
 ['zielsystem','Die Geschäftsführung will Nachhaltigkeit verbessern, hat aber nur eine allgemeine Absicht formuliert. Was macht das Ziel steuerbar?','Messgröße, Ausgangswert, Zieltermin und verantwortliche Rolle festlegen.',['Ein ambitioniertes Ziel ohne Kennzahl veröffentlichen.','Nur die Zahl der Nachhaltigkeitsbesprechungen messen.','Den Zieltermin aus dem Bericht weglassen.'],'Messbare Zielbestandteile ermöglichen Fortschrittskontrolle und Verantwortlichkeit.','Ressourcen können auf konkrete Verbrauchs- oder Prozessverbesserungen gerichtet werden.'],
 ['statistik','Die Zahl der Arbeitsunfälle ist im Quartal null. Welche Aussage lässt sich daraus sicher ableiten?','Nur, dass in diesem Zeitraum keine erfassten Unfälle auftraten; das Risiko ist dadurch nicht ausgeschlossen.',['Der Betrieb ist dauerhaft vollständig sicher.','Präventionsmaßnahmen können eingestellt werden.','Beinaheunfälle sind deshalb statistisch irrelevant.'],'Seltene Ereignisse erlauben keine Garantie über zukünftige Risiken oder Meldequalität.','Der Betrieb setzt Prävention fort und berücksichtigt auch Gefährdungen sowie Beinaheereignisse.'],
 ['projektplanung','Eine Prozessverbesserung soll gleichzeitig in Einkauf, Fertigung und Versand eingeführt werden. Was gehört in einen umsetzbaren Projektauftrag?','Ziel, Umfang, Verantwortliche, Meilensteine und Erfolgskriterien benennen.',['Nur ein Budgetlimit festlegen.','Alle Ideen während der Umsetzung automatisch zum Projektumfang machen.','Die Erfolgskriterien erst nach Abschluss auswählen.'],'Ein klarer Auftrag begrenzt Umfang und macht Fortschritt sowie Ergebnis überprüfbar.','Bereiche können abgestimmt beitragen, ohne dass Zeit oder Ressourcen unkontrolliert ausufern.'],
 ['entscheidungstechnik','Zwei Handlungsoptionen hängen stark von einem unsicheren Absatzwachstum ab. Wie kann die Leitung die Robustheit der Wahl prüfen?','Sensitivitätsanalyse für die entscheidenden Annahmen durchführen.',['Nur den optimistischen Fall rechnen.','Die Unsicherheit durch einen Mittelwert ersetzen und nicht dokumentieren.','Nach der ersten Rechnung keine Parameter mehr verändern.'],'Die Sensitivitätsanalyse zeigt, ab wann sich die Vorteilhaftigkeit einer Option ändert.','Die Geschäftsführung erkennt, welche Annahmen entscheidungskritisch sind und überwacht sie gezielt.'],
 ['wissensmanagement','Nach einer Reklamation wurde eine hilfreiche Korrekturmaßnahme gefunden, die andere Teams nicht kennen. Wie lässt sich organisationales Lernen sichern?','Erkenntnis, Anwendungsbereich und geänderten Standard dokumentieren und betroffene Teams informieren.',['Nur den Einzelfall schließen.','Die Maßnahme ohne Prüfung auf jeden Prozess übertragen.','Die Erfahrung ausschließlich im persönlichen Gedächtnis speichern.'],'Wissenstransfer macht eine geprüfte Erkenntnis zugänglich, ohne ihre Gültigkeit ungeprüft zu verallgemeinern.','Ähnliche Fehler können vermieden werden und Verbesserungen werden über Bereiche hinweg nutzbar.'],
 ['zeitmanagement','Eine Besprechung endet regelmäßig ohne klare Aufgaben und Termine. Welche Maßnahme verbessert die Umsetzung?','Zum Abschluss Entscheidungen, Aufgabenverantwortliche und Fristen protokollieren.',['Die Besprechungszeit verlängern, ohne Ergebnisse festzuhalten.','Das Protokoll nur als Teilnehmerliste führen.','Aufgaben offenlassen, damit mehr Flexibilität bleibt.'],'Verbindliche Ergebnisse machen die Umsetzung nachverfolgbar.','Beschlüsse gehen seltener verloren und Folgearbeit kann gezielt eingeplant werden.'],
 ['statistik','Ein Betrieb meldet eine hohe durchschnittliche Mitarbeiterauslastung. Was muss bei der Interpretation beachtet werden?','Überlastung, Wartezeiten und Verteilung zwischen Personen zusätzlich untersuchen.',['Den Durchschnitt als Beweis für gleichmäßige Auslastung ansehen.','Leerlaufzeiten aus der Datenerhebung entfernen.','Nur die produktivste Person betrachten.'],'Ein Durchschnitt kann ungleiche Verteilung und lokale Engpässe verdecken.','Kapazitätsplanung kann Belastung besser ausgleichen und Ausfallrisiken erkennen.'],
 ['risikomanagement','Ein Cybervorfall legt die Produktionsplanung kurzfristig lahm. Welche organisatorische Vorsorge wäre besonders relevant?','Wiederanlaufverfahren, Verantwortlichkeiten und gesicherte aktuelle Planungsdaten vorbereiten.',['Alle Systeme ohne Wiederherstellungsprüfung sichern.','Notfallentscheidungen erst nach Eintritt des Vorfalls verteilen.','Die Planung ausschließlich auf Papier doppelt führen, ohne Aktualisierung.'],'Ein getesteter Wiederanlaufplan verbindet Datenverfügbarkeit mit klaren Zuständigkeiten.','Die Dauer von Betriebsunterbrechungen kann sinken und Prioritäten werden im Notfall schneller klar.'],
 ['kreativitaet','Bei der Suche nach einer ergonomischen Verbesserung bewertet das Team jede Idee sofort nach Kosten und verwirft viele Vorschläge. Was sollte die Moderation ändern?','Ideenfindung zeitlich von der anschließenden Machbarkeitsbewertung trennen.',['Nur kostengünstige Ideen überhaupt sammeln.','Die Diskussion auf die bisherige Lösung begrenzen.','Die erste umsetzbare Idee ungeprüft als einzig mögliche wählen.'],'Eine getrennte Bewertungsphase erhält zunächst Vielfalt und ermöglicht danach eine realistische Auswahl.','Das Team findet eher mehrere praktikable Optionen für eine spätere Erprobung.'],
 ['personalentwicklung','Mehrere Beschäftigte möchten sich auf eine intern frei werdende Stelle bewerben. Wie unterstützt die Personalentwicklung eine faire Vorbereitung?','Anforderungsprofil und erforderliche Kompetenzen transparent machen und Entwicklungsbedarf besprechen.',['Die Stelle nach Betriebszugehörigkeit ohne Anforderungsabgleich vergeben.','Kriterien erst nach den Bewerbungsgesprächen festlegen.','Allen Bewerbenden denselben Kurs unabhängig vom Bedarf zuweisen.'],'Transparente Anforderungen verbinden Auswahl und individuelle Entwicklung.','Der Betrieb kann interne Nachfolge vorbereiten und Entscheidungen nachvollziehbar begründen.'],
 ['organisation','Ein Prozess enthält doppelte Dateneingaben in Vertrieb und Arbeitsvorbereitung. Welche Analyse sollte vor einer Systemänderung erfolgen?','Informationsbedarf, Datenverantwortung und Übergabepunkte des Prozesses aufnehmen.',['Eine der Eingaben sofort löschen.','Beide Stellen weiterarbeiten lassen und Fehlerquote ignorieren.','Ein neues System kaufen, bevor Anforderungen geklärt sind.'],'Eine Prozessaufnahme verhindert, dass wichtige Prüf- oder Übergabefunktionen versehentlich entfallen.','Medienbrüche lassen sich reduzieren, ohne notwendige Informationskontrollen zu verlieren.'],
 ['analyse','Die Fertigungsauslastung sinkt, weil ein Kunde Aufträge verschiebt. Welche Kennzahlenkombination hilft beim Managementgespräch?','Auftragseingang, Kapazitätsauslastung, Deckungsbeitrag und Liquiditätsvorschau gemeinsam betrachten.',['Nur die Auslastung betrachten und Personal sofort abbauen.','Umsatz der Vorperiode als sichere Prognose verwenden.','Nur den Bankbestand ohne erwartete Zahlungen betrachten.'],'Die Kombination zeigt sowohl wirtschaftliche Tragfähigkeit als auch kurzfristige Zahlungswirkung.','Die Leitung kann Kapazitäts- und Finanzierungsentscheidungen abgestimmt statt isoliert treffen.'],
 ['wissensmanagement','Ein neues Qualitätsmerkmal wird von der Konstruktion festgelegt, aber die Fertigung erfährt es erst nach einer Fehlcharge. Welche Wissensschnittstelle fehlt?','Freigegebene Produktänderungen müssen strukturiert an betroffene Prozessrollen übermittelt werden.',['Die Konstruktion soll Änderungen nicht mehr dokumentieren.','Die Fertigung soll jede Zeichnung täglich selbst vergleichen.','Die Fehlcharge als ausreichende Änderungsmitteilung behandeln.'],'Ein definierter Änderungsfluss verbindet technische Entscheidung und operative Umsetzung.','Neue Anforderungen erreichen die Produktion rechtzeitig und Fehlfertigung wird unwahrscheinlicher.']
);
areas.push({id:'hsq-investition-finanzierung-rechnungswesen-controlling',name:'Investition, Finanzierung, betriebliches Rechnungswesen und Controlling',paragraph:2,items:[
 ['investitionsplanung','Ein CNC-Bearbeitungszentrum kostet deutlich mehr als eine generalüberholte Maschine, bietet aber höhere Präzision. Welche Investitionsprüfung ist sachgerecht?','Anschaffungs- und Folgekosten, Leistungsfähigkeit, Nutzungsdauer und erwartete Erlöse vergleichen.',['Nur den Anschaffungspreis der beiden Anlagen gegenüberstellen.','Die teurere Anlage wählen, weil Präzision grundsätzlich Umsatz garantiert.','Folgekosten erst nach der Bestellung ermitteln.'],'Die Investition muss nach ihrem gesamten wirtschaftlichen Beitrag und den Kosten beurteilt werden.','Der Betrieb kann Kapitalbedarf und erwarteten Nutzen gemeinsam abwägen.'],
 ['investitionsrechnung','Ein Projekt hat eine hohe Anfangsauszahlung und Rückflüsse über mehrere Jahre. Warum ist eine statische Amortisationsrechnung allein begrenzt?','Sie bildet den Zeitwert späterer Zahlungen und Rückflüsse nach der Amortisation nur eingeschränkt ab.',['Sie berücksichtigt immer sämtliche Zahlungsströme mit Abzinsung.','Sie bewertet ausschließlich die Bilanzsumme.','Sie ersetzt automatisch jede Kostenvergleichsrechnung.'],'Die statische Methode liefert eine grobe Rückflussdauer, aber keine vollständige dynamische Vorteilhaftigkeit.','Entscheider ergänzen die Kennzahl um Zahlungszeitpunkte und weitere Wirtschaftlichkeitskriterien.'],
 ['investitionsrechnung','Eine neue Maschine reduziert die Bearbeitungszeit, benötigt aber teure Werkzeuge. Welche Betrachtung hilft beim Vergleich mit der Altanlage?','Kosten und Leistungswirkungen je vergleichbarer Produktionseinheit erfassen.',['Nur die Bearbeitungsminute der neuen Anlage betrachten.','Werkzeugkosten als einmalige Investition behandeln, obwohl sie laufend anfallen.','Die Altanlage wegen ihres bereits bezahlten Kaufpreises als kostenfrei einstufen.'],'Ein Einheitenvergleich bezieht relevante laufende Kosten und Produktivität ein.','Die Wahl kann die tatsächlichen Stückkosten statt bloß nominelle Maschinenzeiten verbessern.'],
 ['investitionsplanung','Die Geschäftsführung muss zwischen einer Ersatzinvestition und einer Kapazitätserweiterung wählen. Welche Frage trennt die Zwecke?','Ob die Maßnahme bestehende Leistung erhält oder zusätzliche Nachfragekapazität schafft.',['Ob beide Anlagen dieselbe Farbe haben.','Ob die Investition im Organigramm eingezeichnet ist.','Ob die Ersatzanlage automatisch keine Finanzierung braucht.'],'Ersatz- und Erweiterungsinvestitionen haben unterschiedliche Ziele und Vergleichsmaßstäbe.','Bedarf und Finanzplanung werden passend zum Investitionszweck aufgestellt.'],
 ['investitionsrechnung','Eine Maschine kann gekauft oder geleast werden. Was muss der Betrieb für einen wirtschaftlichen Vergleich beachten?','Zahlungsreihen, Nutzung, Restwert, Dienstleistungen und Vertragsbedingungen vergleichbar erfassen.',['Kaufpreis mit einer einzelnen Leasingrate vergleichen.','Steuerwirkungen als einzigen Entscheidungsgrund verwenden.','Vertragslaufzeit und Rückgabebedingungen ignorieren.'],'Nur eine vollständige Betrachtung macht unterschiedliche Nutzungs- und Zahlungsmodelle vergleichbar.','Der Betrieb erkennt die Auswirkungen auf Liquidität, Risiko und Nutzungsspielraum.'],
 ['finanzplanung','Der Absatzplan sieht Gewinn vor, aber Kunden zahlen erst nach mehreren Wochen. Was zeigt eine Liquiditätsplanung?','Wann Einzahlungen und Auszahlungen anfallen und ob Zwischenfinanzierung nötig wird.',['Ob der Absatzplan rechnerisch einen Gewinn zeigt.','Wie hoch der bilanzielle Maschinenwert ist.','Welche Mitarbeitenden die meisten Stunden leisten.'],'Liquiditätsplanung bildet Zahlungszeitpunkte ab, die vom Erfolg abweichen können.','Zahlungsschwierigkeiten lassen sich vor Fälligkeit erkennen und geordnet adressieren.'],
 ['finanzplanung','Ein Unternehmen plant die Anschaffung einer Maschine und mehrere Materialbestellungen. Welche Größe muss es für den Finanzbedarf zusammenführen?','Investitionsauszahlung, laufenden Betriebsmittelbedarf und verfügbare Finanzierung.',['Nur das Eigenkapital am letzten Bilanzstichtag.','Den Jahresumsatz ohne Zahlungszeitpunkte.','Die Abschreibung als tatsächlich verfügbare Einzahlung.'],'Finanzierungsbedarf umfasst die geplante Investition und den Liquiditätsbedarf des Betriebs.','Die Finanzierung wird nicht nur für den Kauf, sondern auch für die Anlaufphase dimensioniert.'],
 ['finanzplanung','Die Bank gewährt eine Kreditlinie, deren Limit regelmäßig überprüft wird. Welche Information ist für die Limithöhe relevant?','Planbare Liquiditätsspitzen, Rückführungsfähigkeit und vereinbarte Sicherheiten.',['Der höchste jemals erzielte Monatsumsatz allein.','Die Summe aller Angebote unabhängig von Zuschlagswahrscheinlichkeit.','Nur die Anschaffungskosten der Maschine.'],'Eine Kreditlinie dient kurzfristigem Bedarf; Limit und Rückführung müssen zum tatsächlichen Liquiditätsprofil passen.','Der Betrieb begrenzt Finanzierungskosten und vermeidet eine strukturelle Abhängigkeit vom Kontokorrent.'],
 ['finanzierungsarten','Ein Betrieb finanziert eine langlebige Maschine ausschließlich mit täglich kündbarem Kontokorrent. Welches Risiko entsteht?','Laufzeit- und Refinanzierungsrisiko, weil die Finanzierung kürzer als die Nutzung sein kann.',['Das Risiko, dass die Maschine über die Laufzeit keine Abschreibung hat.','Ein Anspruch auf unbegrenzte Kreditverlängerung.','Eine automatische Umwandlung des Kredits in Eigenkapital.'],'Die Fristenkongruenz sollte bei langfristigen Vermögenswerten berücksichtigt werden.','Der Betrieb senkt das Risiko, dass kurzfristige Rückzahlung die Investition oder Liquidität gefährdet.'],
 ['finanzierungsarten','Die Eigentümer erwägen eine Eigenkapitalzuführung statt eines weiteren Kredits. Welche Abwägung ist zentral?','Kapitalverfügbarkeit, Einflussrechte, Risiko und langfristige Belastung vergleichen.',['Eigenkapital ohne Auswirkungen auf Eigentum oder Rendite annehmen.','Nur den Nominalzins eines Kredits betrachten.','Eigenkapital als kurzfristig jederzeit rückzahlbare Verbindlichkeit behandeln.'],'Eigen- und Fremdfinanzierung unterscheiden sich bei Kontrolle, Rückzahlung und Risikotragung.','Die Finanzierungsstruktur kann tragfähiger werden, wenn Kapitalgeberinteressen berücksichtigt sind.'],
 ['finanzierungsarten','Ein Lieferant bietet ein verlängertes Zahlungsziel, während die Bank einen kurzfristigen Kredit anbietet. Welche Prüfung ist sinnvoll?','Gesamtkosten, Fälligkeiten und Auswirkungen auf Lieferantenbeziehung und Liquiditätsplan vergleichen.',['Das verlängerte Zahlungsziel automatisch als kostenlos ansehen.','Beide Finanzierungsformen ohne Fälligkeit in den Plan eintragen.','Nur nach dem Zinssatz entscheiden und Vertragsbedingungen auslassen.'],'Zahlungsziel und Kredit haben unterschiedliche Kosten- und Beziehungsfolgen.','Der Betrieb kann kurzfristigen Bedarf decken, ohne unbeabsichtigt die Lieferfähigkeit zu beeinträchtigen.'],
 ['bilanz','Ein Betrieb erhält ein Darlehen und verwendet es sofort zur Maschinenzahlung. Welche Wirkung hat die Kreditaufnahme im Grundsatz?','Bankmittel und Verbindlichkeiten steigen zunächst; der spätere Kauf tauscht Zahlungsmittel gegen Anlagevermögen.',['Das Eigenkapital steigt unmittelbar um den Darlehensbetrag.','Der Darlehensbetrag wird sofort vollständig als Aufwand gebucht.','Die Maschine erzeugt automatisch einen Umsatzerlös.'],'Finanzierung und Investitionskauf sind getrennte Geschäftsvorfälle und verändern unterschiedliche Bilanzpositionen.','Die Bilanz zeigt Herkunft und Verwendung der Mittel getrennt nachvollziehbar.'],
 ['bilanz','Ein Kunde bezahlt eine offene Forderung per Überweisung. Welche unmittelbare Bilanzveränderung ist zu erwarten?','Bankguthaben steigt und Forderungen sinken, der Zahlungseingang ist nicht nochmals Umsatz.',['Bankguthaben und Umsatz steigen erneut um denselben Betrag.','Verbindlichkeiten sinken ohne Zahlungsabgang.','Das Eigenkapital steigt automatisch um den Zahlungseingang.'],'Der Zahlungseingang gleicht eine bereits erfasste Forderung aus und ist keine zweite Leistungserfassung.','Umsatz und Liquidität werden nicht doppelt gezählt.'],
 ['erfolgsrechnung','Eine Maschine wird gekauft und im selben Moment vollständig bezahlt. Warum ist der Kaufpreis nicht automatisch sofortiger Aufwand in voller Höhe?','Das Anlagegut wird genutzt; sein Werteverzehr wird grundsätzlich über Nutzungsperioden abgebildet.',['Weil Investitionen nie Kosten verursachen.','Weil die Zahlung die Bilanz nicht verändert.','Weil der Kaufpreis automatisch als Vorrat gilt.'],'Anschaffung und periodischer Werteverzehr sind unterschiedliche Sachverhalte.','Die Ergebnisrechnung verteilt die Nutzungskosten periodengerechter.'],
 ['kostenrechnung','Stahlverbrauch kann einem Kundenauftrag mengenmäßig direkt zugeordnet werden. Wie ist er in der Kalkulation grundsätzlich zu behandeln?','Als auftragsbezogene Materialeinzelkosten erfassen.',['Als stets fixe Verwaltungsgemeinkosten buchen.','Als Finanzierungsertrag abziehen.','Nur nach Jahresende pauschal auf alle Aufträge verteilen.'],'Direkte Zurechnung verbessert die verursachungsgerechte Auftragskalkulation.','Angebots- und Nachkalkulation zeigen den Materialbeitrag des einzelnen Auftrags.'],
 ['kostenrechnung','Der Maschinenstundensatz steigt, weil weniger produktive Stunden auf die gleiche fixe Kostenbasis verteilt werden. Welche Ursache erklärt den Effekt?','Die geringere Bezugsmenge erhöht die zugerechneten Fixkosten je Maschinenstunde.',['Die Fixkosten sind zwingend im selben Umfang gestiegen.','Die Materialeinzelkosten werden zu Erlösen.','Die Maschine hat durch geringere Nutzung automatisch einen höheren Marktwert.'],'Bei geringerer Beschäftigung verteilen sich unveränderte Fixkosten auf weniger Leistungseinheiten.','Die Leitung erkennt Auslastungseffekte und bewertet Kostensätze nicht als reine Preisänderung.'],
 ['kostenrechnung','Ein Auftrag weist einen positiven Deckungsbeitrag aus, deckt aber nicht alle langfristigen Gemeinkosten. Wie sollte die Leitung den Auftrag beurteilen?','Kurzfristige Zusatzentscheidung und langfristige Vollkostendeckung getrennt bewerten.',['Positiven Deckungsbeitrag mit sicherem Gesamtgewinn gleichsetzen.','Alle fixen Kosten als für immer unveränderlich behandeln.','Den Auftrag unabhängig von freien Kapazitäten ablehnen.'],'Der Deckungsbeitrag beantwortet eine andere Frage als die vollständige langfristige Kostendeckung.','Die Annahmeentscheidung kann kurzfristige Kapazitätsnutzung und langfristige Preisstrategie berücksichtigen.'],
 ['kostenrechnung','Eine Abteilung verbraucht mehr Hilfsstoffe, als ihr zugeordnet wurde. Welche Kostenstelleninformation hilft, die Abweichung zu lokalisieren?','Verbrauch und Kostenstelle mit Planwerten sowie Leistungsmenge vergleichen.',['Gesamtkosten des Unternehmens ohne Bereichsbezug.','Nur den Umsatz des Vorjahres.','Die Hilfsstoffe dem Kunden mit dem höchsten Auftragswert zuweisen.'],'Kostenstellenrechnung zeigt, wo Kosten anfallen und welche Bezugsgrößen sich verändert haben.','Verantwortliche können gezielte Maßnahmen prüfen, statt pauschal Kosten zu kürzen.'],
 ['kalkulation','Ein Angebot wird unter Einbezug von Material und Fertigungszeit kalkuliert, aber Rüstkosten fehlen. Was droht?','Der Angebotspreis unterschätzt die tatsächlichen Auftragskosten und kann die Marge überzeichnen.',['Die Forderung wird bei Annahme zu hoch ausgewiesen.','Die Rüstzeit erhöht automatisch den Deckungsbeitrag.','Der Materialbestand sinkt ohne Materialverbrauch.'],'Vollständige auftragsbezogene Kostenbestandteile sind für eine tragfähige Kalkulation wichtig.','Der Betrieb vermeidet Aufträge, die nur scheinbar wirtschaftlich sind.'],
 ['controlling','Die tatsächlichen Materialkosten übersteigen den Plan. Welche erste Controllingreaktion ist angemessen?','Preis- und Mengenabweichung getrennt analysieren und Ursachen belegen.',['Den Plan nachträglich auf Ist setzen.','Die Abweichung ohne Prüfung dem Einkauf anlasten.','Materialkosten im Folgemonat verbuchen.'],'Eine Abweichungsanalyse trennt unterschiedliche Ursachen und verhindert willkürliche Zuschreibungen.','Maßnahmen können am Einkaufspreis, Verbrauch oder Produktmix ansetzen.'],
 ['controlling','Eine Absatzprognose wurde trotz negativer Marktindikatoren nicht angepasst. Welche Controllingfunktion wurde vernachlässigt?','Planung mit aktuellen Informationen fortschreiben und Abweichungen früh melden.',['Die Bilanzaufstellung durch den Vertrieb ersetzen.','Abweichungen nur nach Jahresende bewerten.','Prognosen grundsätzlich unverändert halten.'],'Controlling unterstützt Steuerung durch aktuelle Plan-Ist-Informationen und Prognosen.','Kapazitäts- und Liquiditätsentscheidungen reagieren früher auf veränderte Nachfrage.'],
 ['kennzahlen','Die Eigenkapitalquote sinkt, während die Bilanzsumme wegen eines Kredits stark wächst. Was muss bei der Interpretation beachtet werden?','Absolute Werte, Finanzierungsvorgang und zeitlichen Verlauf gemeinsam betrachten.',['Eine sinkende Quote beweist allein eine Insolvenz.','Kreditaufnahme als Eigenkapitalzufluss behandeln.','Nur die Quote ohne Bilanzstruktur auswerten.'],'Kennzahlen brauchen Kontext und dürfen nicht als alleinige Diagnose verwendet werden.','Die Geschäftsleitung kann Kapitalstruktur und Schuldentragfähigkeit differenzierter beurteilen.'],
 ['steuerung','Eine Kostenstelle liegt über Budget, weil ein ungeplanter Sicherheitsmangel behoben werden musste. Was ist eine sachgerechte Steuerungsreaktion?','Abweichung und Sicherheitsgrund dokumentieren, Prognose aktualisieren und Freigabeweg beachten.',['Die erforderliche Reparatur unterlassen, um den Plan einzuhalten.','Kosten in eine andere Kostenstelle verschieben.','Budgetabweichungen grundsätzlich ignorieren.'],'Budgetsteuerung muss sachliche Notwendigkeit und Verantwortungs-/Freigaberegeln berücksichtigen.','Sicherheitsmaßnahmen werden nicht aus rein formaler Budgettreue verzögert und Kosten bleiben transparent.'],
 ['kostenrechnung','Die Geschäftsleitung will wissen, ob die interne Lackierung oder Fremdvergabe wirtschaftlicher ist. Welche Kosten sind für den Vergleich besonders relevant?','Vermeidbare interne Kosten und externe Gesamtkosten einschließlich Qualität und Logistik vergleichen.',['Alle internen Fixkosten als automatisch einsparbar behandeln.','Nur den Fremdpreis ohne Transport oder Prüfaufwand ansehen.','Historische Anschaffungskosten der Lackierkabine allein vergleichen.'],'Entscheidungsrelevant sind Kosten, die sich mit der Alternative ändern, sowie Leistungsfolgen.','Die Make-or-buy-Entscheidung berücksichtigt echte Einsparungen und Servicefolgen.'],
 ['investitionsplanung','Ein Unternehmen möchte eine energieeffiziente Maschine kaufen. Welche Zusatzinformation verbessert die Investitionsentscheidung?','Energieeinsparung, Nutzungsprofil, Wartung und erforderliche Investitionskosten abschätzen.',['Mit einer maximalen Werbeangabe rechnen, ohne Betriebsstunden zu prüfen.','Energieverbrauch als einzigen Kostenfaktor behandeln.','Wartungsaufwand aus dem Vergleich ausschließen.'],'Nutzen hängt vom tatsächlichen Einsatz und den gesamten Folgekosten ab.','Die erwartete Einsparung wird an der realen Auslastung statt an Idealbedingungen gemessen.'],
 ['finanzplanung','Ein Kunde verschiebt eine große Zahlung, während Löhne und Lieferantenrechnungen fällig werden. Welche kurzfristige Maßnahme ist zuerst nötig?','Aktualisierte Liquiditätsvorschau mit Fälligkeiten und verfügbaren Finanzierungsoptionen erstellen.',['Die offene Forderung als bereits verfügbares Bankguthaben zählen.','Alle Lieferanten automatisch später bezahlen, ohne Vereinbarung.','Den Auftragserfolg als ausreichende Liquiditätsgarantie ansehen.'],'Eine Fälligkeitsübersicht zeigt die zeitliche Lücke und die verfügbaren Handlungsmöglichkeiten.','Der Betrieb kann rechtzeitig kommunizieren und Zahlungsunfähigkeit vermeiden helfen.']
]});
areas[1].items.push(
 ['investitionsrechnung','Eine Investition wirkt erst ab 70 Prozent Auslastung vorteilhaft. Welche Prüfung testet ausdrücklich die Belastbarkeit dieser Schwellenannahme?','Nachfrage- und Kapazitätsannahmen auf Plausibilität prüfen und Auslastungsschwellen variieren.',['Die Investition mit Vollauslastung berechnen und Absatzrisiken im laufenden Planungsreview nachhalten.','Die Prognose mit der erwarteten Auslastung rechnen und die 70-Prozent-Schwelle nur als Warnwert im laufenden Betrieb überwachen.','Nur die technische Lebensdauer bewerten.'],'Die Vorteilhaftigkeit hängt von einer kritischen Annahme ab, die mit realistischen Szenarien geprüft werden muss.','Das Unternehmen kann erkennen, wie empfindlich die Investition auf schwächere Auslastung reagiert.'],
 ['investitionsrechnung','Zwei Maschinen haben gleiche jährliche Kosten, aber unterschiedliche Produktionsmengen. Welche Vergleichsgröße ist zweckmäßig?','Kosten je nutzbarer Leistungseinheit bei gleicher Qualitätsanforderung berechnen.',['Gesamtkosten ohne Mengeneinheit vergleichen.','Nur die maximale Herstellerleistung verwenden.','Die Maschine mit höherem Anschaffungspreis wählen.'],'Ein Kostenvergleich je Leistungseinheit macht unterschiedliche Mengen vergleichbar.','Die Kapazitätsentscheidung berücksichtigt die tatsächlich benötigte Leistung und Qualität.'],
 ['investitionsplanung','Ein Betrieb plant eine Erweiterung, doch die vorgelagerte Stromversorgung reicht möglicherweise nicht. Was muss in die Investitionsplanung einbezogen werden?','Ergänzende Infrastruktur, Umsetzungskosten und zeitliche Abhängigkeiten erfassen.',['Nur den Maschinenpreis in den Finanzierungsantrag aufnehmen.','Versorgungsengpässe nach der Lieferung behandeln.','Die Infrastruktur als kostenlose Voraussetzung annehmen.'],'Ergänzende Maßnahmen können notwendige Bestandteile und Kosten der Investition sein.','Verzögerungen und nicht eingeplante Zusatzfinanzierung werden eher vermieden.'],
 ['investitionsrechnung','Ein Projekt erzielt positive Jahresüberschüsse, aber benötigt hohe Vorleistungen lange vor dem Zahlungseingang. Welche ergänzende Rechnung ist entscheidend?','Zahlungsströme nach Zeitpunkt planen und dynamisch auf ihre Vorteilhaftigkeit untersuchen.',['Nur die erwartete Gewinnsumme addieren.','Abschreibungen als Einzahlungen behandeln.','Kundenzahlungen ohne Fälligkeit ansetzen.'],'Erfolg und Liquiditätsverlauf sind verschieden; zeitliche Zahlungsströme beeinflussen den Kapitalwert.','Die Leitung erkennt sowohl Rendite als auch zwischenzeitliche Finanzierungslücken.'],
 ['finanzplanung','Die monatlichen Einzahlungen schwanken saisonal stark. Welcher Planungsansatz passt besser als ein gleichbleibender Monatsdurchschnitt?','Rollierende Liquiditätsplanung mit erwarteten Fälligkeiten und Saisonverlauf erstellen.',['Den Jahresumsatz gleichmäßig auf alle Monate verteilen.','Nur den aktuellen Kassenbestand betrachten.','Schwache Monate aus dem Plan entfernen.'],'Ein rollierender Plan bildet erwartete Zahlungszeitpunkte und Änderungen ab.','Finanzierungsbedarf kann vor saisonalen Engpässen erkannt und angepasst werden.'],
 ['finanzplanung','Ein Unternehmen gewährt Kunden längere Zahlungsziele, um wettbewerbsfähig zu bleiben. Welche Folge ist in der Finanzplanung zu berücksichtigen?','Zusätzlicher Forderungsbestand und späterer Liquiditätszufluss einplanen.',['Das Zahlungsziel als sofortigen Zahlungseingang behandeln.','Den Preisnachlass gleich null setzen, unabhängig von Finanzierungskosten.','Die Forderung aus der Bilanzplanung entfernen.'],'Längere Zahlungsziele binden Kapital bis zum Zahlungseingang.','Konditionen können unter Berücksichtigung von Absatzwirkung und Finanzierungskosten bewertet werden.'],
 ['finanzierungsarten','Eine Maschine soll durch ein langfristiges Darlehen finanziert werden. Die Bank verlangt Sicherheiten. Was sollte die Geschäftsführung vor Zusage klären?','Sicherheitenumfang, Verwertungsfolgen, Laufzeit und gesamte Belastung prüfen.',['Die Sicherheiten als kostenfreie Formalität behandeln.','Dem Kreditgeber sämtliche Vermögenswerte ohne Dokumentation anbieten.','Nur die monatliche Rate betrachten.'],'Kreditkonditionen umfassen mehr als die Rate; Sicherheiten binden Vermögen und tragen Verwertungsrisiken.','Der Betrieb kann Tragfähigkeit und mögliche Folgen eines Zahlungsausfalls abwägen.'],
 ['finanzierungsarten','Der Betrieb erzielt einen Gewinn und möchte ihn im Unternehmen belassen statt auszuschütten. Welche Finanzierungsform liegt nahe?','Selbstfinanzierung durch Einbehaltung von erwirtschafteten Mitteln prüfen.',['Fremdfinanzierung aus einer Bankeinlage.','Außenfinanzierung durch Lieferantenrechnung.','Abschreibung als automatisch verfügbare Finanzierung gleichsetzen.'],'Einbehaltene Gewinne können die Innenfinanzierung stärken, sofern ausreichende Zahlungsmittel vorhanden sind.','Eigenmittelbasis kann wachsen, ohne dass ein neues Darlehen aufgenommen wird.'],
 ['finanzierungsarten','Ein kurzfristiger Auftrag erfordert zusätzliche Materialien; der Kunde zahlt nach Abnahme. Welche Finanzierung passt zur vorübergehenden Vorfinanzierung?','Kurzfristigen Betriebsmittelbedarf und Rückflusszeitpunkt mit geeigneten Kredit- oder Lieferantenoptionen abgleichen.',['Eine langfristige Maschinenfinanzierung für jeden Materialeinkauf abschließen.','Die Rechnung als Eigenkapital verbuchen.','Fälligkeiten ignorieren und auf einen Gewinn vertrauen.'],'Die Finanzierung sollte Zweck, Dauer und Rückfluss des Bedarfs berücksichtigen.','Die Kapitalbindung des Auftrags kann überbrückt werden, ohne die Investitionsfinanzierung unnötig zu belasten.'],
 ['bilanz','Der Eigentümer zahlt zusätzliches Kapital auf das Firmenkonto ein. Welche Bilanzwirkung ist grundsätzlich naheliegend?','Bankguthaben und Eigenkapital steigen, sofern es sich tatsächlich um eine Einlage handelt.',['Bankguthaben und Lieferantenverbindlichkeiten steigen zwingend gemeinsam.','Der Betrag wird sofort als Umsatzerlös ausgewiesen.','Das Eigenkapital sinkt um den Einzahlungsbetrag.'],'Eine Einlage erhöht die Zahlungsmittel und die Eigenkapitalposition, ohne Umsatz aus Leistungserbringung zu sein.','Die Finanzierung wird als Eigentümerbeitrag transparent von operativen Erträgen getrennt.'],
 ['bilanz','Ein Betrieb erhält Material auf Rechnung und nutzt es später für einen Auftrag. Was entsteht beim Wareneingang zunächst?','Vorräte beziehungsweise Materialbestand und eine Verbindlichkeit gegenüber dem Lieferanten.',['Sofort ein Kundenerlös.','Ausschließlich ein Zahlungsmittelabfluss.','Eine Erhöhung des Eigenkapitals.'],'Lieferung und spätere Zahlung sind getrennte Vorgänge; Materialbestand und Schuld entstehen zunächst.','Bestände und offene Verpflichtungen werden im Abschluss nicht verwechselt.'],
 ['erfolgsrechnung','Ein Kunde reklamiert eine bereits fakturierte Leistung und der Betrieb gewährt eine Preisgutschrift. Welche Ergebniswirkung ist zu untersuchen?','Die Erlösminderung und ihre Zuordnung zur betroffenen Periode berücksichtigen.',['Die Gutschrift als Materialzugang erfassen.','Den Rechnungsbetrag unverändert als endgültigen Erlös behandeln.','Die Gutschrift als Eigenkapitaleinlage verbuchen.'],'Eine nachträgliche Preisänderung beeinflusst den Erlös und muss nachvollziehbar erfasst werden.','Auftragsergebnis und Kundenforderung spiegeln die vereinbarte Korrektur wider.'],
 ['erfolgsrechnung','Die Maschine fällt eine Woche aus. Der Betrieb will den Liefertermin durch externe Fertigung sichern. Welche zusätzliche Kostenposition sollte er in den Vergleich aufnehmen?','Angebotspreis externer Fertigung mit entfallenden internen variablen Kosten und zusätzlichem Koordinationsaufwand vergleichen.',['Nur die bilanzielle Abschreibung als vollständige Ausfallwirkung ansehen.','Den gesamten geplanten Wochenumsatz als Ausfall ansetzen und mögliche Nachproduktion im Folgemonat als separates Zusatzgeschäft behandeln.','Die Stillstandszeit ohne Bezug zu Aufträgen ignorieren.'],'Bei Fremdvergabe sind deren Angebotspreis, vermeidbare interne variable Kosten und zusätzlicher Koordinationsaufwand zu vergleichen.','Die Instandhaltungsentscheidung berücksichtigt den gesamten wirtschaftlichen Schaden.'],
 ['kostenrechnung','Ein Produkt wird in kleinen Losen hergestellt und verursacht viele Rüstvorgänge. Welcher Zuschlag könnte die verursachungsgerechtere Kalkulation unterstützen?','Rüstkosten nach Anzahl oder Aufwand der Rüstvorgänge auf Produkte verteilen.',['Rüstkosten allein nach Materialgewicht verteilen.','Alle Rüstkosten dem größten Kunden zurechnen.','Rüstkosten aus der Kalkulation entfernen.'],'Ein geeigneter Kostentreiber bildet den Zusammenhang zwischen Rüstaufwand und Losstruktur besser ab.','Kleinserien werden realistischer kalkuliert und nicht durch grobe Verteilung verzerrt.'],
 ['kostenrechnung','Die Fertigung verbraucht mehr Stahl als die Stückliste vorsieht. Welche Betrachtung trennt Preis- von Verbrauchseffekt?','Sollmenge und Istmenge sowie Planpreis und Istpreis getrennt vergleichen.',['Nur den Gesamtbetrag der Materialrechnung ansehen.','Den Mehrverbrauch mit dem höheren Einkaufspreis erklären, ohne Mengen zu prüfen.','Die Stückliste nachträglich an den Istverbrauch anpassen.'],'Eine getrennte Mengen- und Preisabweichung zeigt, ob Ursache im Prozess oder Einkauf liegt.','Korrektur kann gezielt an Beschaffung oder Fertigung ansetzen.'],
 ['kostenrechnung','Ein Gemeinkostenzuschlag basiert auf einer einzigen Kostenbasis, obwohl Produkte sehr unterschiedliche Prüfaufwände haben. Welche Verbesserung ist naheliegend?','Geeignete verursachungsnahe Bezugsgrößen oder differenzierte Kostentreiber prüfen.',['Den Zuschlag pauschal erhöhen.','Prüfaufwand vollständig als Einzelkosten jedes Produkts mit gleichem Wert erfassen.','Die Kalkulation ohne Gemeinkosten fortführen.'],'Eine passende Bezugsgröße verbessert die Zurechnung heterogener Gemeinkosten.','Produktkosten und Preisentscheidungen werden weniger durch Quersubventionierung verzerrt.'],
 ['kalkulation','Ein Kunde verlangt eine Sonderverpackung, die im Standardangebot nicht enthalten war. Was ist vor Preisbestätigung zu kalkulieren?','Zusätzliche Material-, Arbeits- und gegebenenfalls Logistikkosten der Sonderleistung erfassen.',['Die Verpackung als kostenlose Marketingmaßnahme behandeln.','Den Standardpreis unverändert lassen, ohne Leistungsumfang zu prüfen.','Die Mehrkosten nachträglich ohne Vereinbarung berechnen.'],'Eine Leistungsänderung kann die Kosten verändern und sollte vor einer verbindlichen Zusage bewertet werden.','Der Betrieb schützt Auftragsmarge und schafft klare Kundenerwartungen.'],
 ['controlling','Ein Projekt unterschreitet das Investitionsbudget, verzögert sich aber stark. Welche Kennzahlensicht ist für die Steuerung nötig?','Kostenstand zusammen mit Terminfortschritt und erreichtem Leistungsumfang bewerten.',['Niedrige Ausgaben als sicheren Projekterfolg werten.','Verzögerungen nicht betrachten, solange Budget frei ist.','Nur den Prozentsatz der ausgegebenen Mittel melden.'],'Ein Projekt kann kostengünstig erscheinen, weil Arbeit noch nicht erbracht wurde.','Die Leitung kann Termin- und Leistungsrisiken trotz unterschrittenem Budget früh erkennen.'],
 ['controlling','Eine Prognose wird jeden Monat knapp verfehlt und nachträglich an den Istwert angepasst. Welche Steuerungsverbesserung ist sinnvoll?','Prognoseannahmen und Abweichungsgründe nachvollziehbar festhalten und unabhängig aktualisieren.',['Die Prognose immer unverändert lassen.','Jede Abweichung als zufälliges Ereignis deklarieren.','Prognose und Istwert gleichsetzen, um Abweichungen zu vermeiden.'],'Eine belastbare Prognose soll erwartete Entwicklung zeigen, nicht rückwirkend den Istwert kopieren.','Entscheidungen basieren auf einer ehrlichen Einschätzung künftiger Risiken.'],
 ['kennzahlen','Der Umsatz je Beschäftigtem steigt, gleichzeitig wird ein größerer Teil der Fertigung ausgelagert. Was ist bei der Kennzahl zu beachten?','Veränderten Leistungsumfang und Fremdleistungsanteil in die Interpretation einbeziehen.',['Produktivität allein aus der Quote als verbessert bezeichnen.','Fremdleistungen als eigene Beschäftigtenstunden zählen.','Die Kennzahl ohne Periodenvergleich beurteilen.'],'Eine Kennzahl verändert sich auch durch Organisationsgrenzen und Fremdbezug.','Die Leitung unterscheidet echte Produktivitätssteigerung von einer Verschiebung des Leistungsumfangs.'],
 ['steuerung','Ein Absatzbereich überschreitet sein Werbebudget, weil eine Kampagne unerwartet erfolgreich läuft. Was sollte Controlling tun?','Zusatzaufwand, erwarteten Nutzen und erforderliche Freigabe gegen die aktualisierte Planung abwägen.',['Die Kampagne sofort stoppen, ohne Wirkung zu prüfen.','Zusatzkosten außerhalb der Buchhaltung führen.','Mehrbudget automatisch freigeben, nur weil die Nachfrage steigt.'],'Eine positive Entwicklung kann zusätzliche Ausgaben rechtfertigen, benötigt aber transparente Steuerung.','Das Unternehmen kann Wachstumschancen nutzen und dennoch Budgetdisziplin wahren.'],
 ['investitionsplanung','Ein Unternehmen erwägt den Kauf eines gebrauchten Gebäudes. Welche Entscheidungsvorbereitung sollte neben dem Kaufpreis erfolgen?','Zustand, notwendige Modernisierung, Standortfolgen und Finanzierung prüfen.',['Den Kaufpreis als vollständigen Gesamtaufwand ansehen.','Finanzierung erst nach bindender Unterzeichnung verhandeln.','Miet- und Kaufoptionen ohne Nutzungshorizont vergleichen.'],'Gebäudekauf kann zusätzliche Instandsetzungs-, Umzugs- und Finanzierungslasten mit sich bringen.','Der Betrieb vermeidet eine Investition, deren tatsächlicher Kapitalbedarf unterschätzt wurde.'],
 ['finanzplanung','Eine Forderung ist überfällig, aber der Kunde bestreitet einen Teil der Leistung. Wie sollte die Liquiditätsprognose damit umgehen?','Zahlungseingang risikogewichtet und zeitlich vorsichtig planen, Klärung separat verfolgen.',['Den vollen Betrag als sichere Einzahlung zum ursprünglichen Termin zählen.','Die Forderung endgültig streichen, bevor sie geprüft wurde.','Die bestrittene Forderung als Bankguthaben behandeln.'],'Eine unsichere Forderung darf nicht wie verfügbares Zahlungsmittel behandelt werden.','Die Prognose unterschätzt kurzfristigen Finanzierungsbedarf seltener.'],
 ['finanzierungsarten','Die Hausbank bietet einen Festzinskredit und einen variabel verzinsten Kredit an. Welche Überlegung ist wesentlich?','Zinsänderungsrisiko, Planungssicherheit, Laufzeit und mögliche Gesamtkosten abwägen.',['Variablen Zins als dauerhaft niedriger garantieren.','Nur den ersten Monatszins vergleichen.','Festzins automatisch als kostenfrei ansehen.'],'Die Kreditform verteilt Zinsänderungsrisiko und Planungssicherheit unterschiedlich.','Die Finanzierung kann passend zur Risikotragfähigkeit und Planbarkeit gewählt werden.'],
 ['kostenrechnung','Ein Produktionsauftrag nutzt eine knappe CNC-Stunde, die auch für einen anderen Auftrag eingesetzt werden könnte. Welche Zusatzgröße ist für die Annahmeentscheidung relevant?','Deckungsbeitrag je Engpasseinheit und entgangene Alternative vergleichen.',['Nur den absoluten Umsatz des Auftrags betrachten.','Die Engpasszeit als kostenfrei behandeln.','Den höchsten Stückdeckungsbeitrag ohne Zeitbezug wählen.'],'Bei knapper Kapazität entscheidet die relative Wertschöpfung je Engpasseinheit.','Die begrenzte Maschinenzeit wird eher Aufträgen mit höherem Ergebnisbeitrag zugeordnet.']
);
areas.push({id:'hsq-logistik',name:'Logistik',paragraph:3,items:[
 ['beschaffungsbedarf','Die Fertigung plant drei Aufträge, aber der Materialbedarf ist nur für zwei vollständig ermittelt. Was sollte der Einkauf vor Bestellung klären?','Stücklisten und Fertigungspläne auf Vollständigkeit prüfen und offenen Bedarf bestätigen lassen.',['Den Verbrauch des fehlenden Auftrags aus dem Vorjahresumsatz schätzen.','Für alle Werkstoffe pauschal dieselbe Menge bestellen.','Erst während der Fertigung feststellen, welche Teile fehlen.'],'Eine belastbare Bedarfsermittlung geht der Bestellung voraus und reduziert Fehl- oder Überbestände.','Material wird gezielter beschafft und Produktionsunterbrechungen werden unwahrscheinlicher.'],
 ['lieferantenauswahl','Ein Lieferant bietet den niedrigsten Preis, hatte aber zuletzt häufig verspätet geliefert. Wie sollte die Auswahl erfolgen?','Preis, Qualität, Zuverlässigkeit und Lieferzeit anhand gewichteter Kriterien bewerten.',['Den niedrigsten Preis automatisch annehmen.','Verspätungen bei der Entscheidung nicht berücksichtigen.','Nur die Entfernung zum Werk vergleichen.'],'Lieferzuverlässigkeit beeinflusst Bestand, Produktion und Kundentermine und muss in die Entscheidung einfließen.','Die Beschaffung kann Gesamtkosten und Versorgungssicherheit gemeinsam abwägen.'],
 ['beschaffungsstrategie','Ein Spezialbauteil ist nur bei einem Anbieter erhältlich und hat lange Lieferzeit. Welche Beschaffungsstrategie reduziert das Risiko?','Versorgungsrisiko, Sicherheitsbestand, Alternativqualifikation und Lieferantenkommunikation prüfen.',['Just-in-time ohne Absicherung einsetzen.','Alle Lagerbestände dieses Bauteils sofort verbrauchen.','Den Lieferanten erst bei einem Stillstand kontaktieren.'],'Bei kritischer Einzelquelle muss die Versorgung strategisch abgesichert werden.','Produktionsstillstände durch Lieferausfall werden weniger wahrscheinlich.'],
 ['bestellmenge','Ein Betrieb bestellt sehr große Lose, um Mengenrabatte zu erhalten, und hat dadurch hohe Lagerkosten. Was ist sinnvoll?','Einkaufsvorteil gegen Kapitalbindung, Lagerkosten und Obsoleszenzrisiko abwägen.',['Jeden Rabatt unabhängig von Gesamtkosten annehmen.','Lagerkosten aus der Wirtschaftlichkeitsrechnung auslassen.','Bestellmengen ausschließlich nach Palettengröße bestimmen.'],'Ein niedriger Einstandspreis kann durch zusätzliche Bestandskosten überkompensiert werden.','Die Bestellmenge orientiert sich stärker an den Gesamtkosten und dem tatsächlichen Bedarf.'],
 ['meldebestand','Der durchschnittliche Verbrauch eines Werkstoffs steigt wegen neuer Aufträge, die Wiederbeschaffungszeit bleibt gleich. Welche Bestandsgröße ist zu überprüfen?','Meldebestand und Sicherheitsbestand an den veränderten Verbrauch anpassen.',['Den Meldebestand unverändert lassen, weil Lieferzeit gleich blieb.','Den Höchstbestand auf null setzen.','Nur die Inventurhäufigkeit reduzieren.'],'Der erwartete Verbrauch während der Lieferzeit ist höher und kann eine frühere Bestellung erfordern.','Fehlmengen werden seltener, während die Bestandssteuerung an den aktuellen Auftragseingang angepasst wird.'],
 ['sicherheitsbestand','Die Lieferzeit eines Standardlagers schwankt stärker als bisher. Welches Ziel erfüllt ein angemessener Sicherheitsbestand?','Ungewissheit in Verbrauch oder Wiederbeschaffung teilweise abfedern.',['Alle denkbaren Lieferausfälle dauerhaft vollständig ausschließen.','Den gesamten Jahresbedarf als Reserve lagern.','Den Lieferanten von seiner Terminverantwortung entbinden.'],'Ein Sicherheitsbestand puffert Risiken, verursacht aber selbst Kapital- und Lagerkosten.','Die Geschäftsführung kann das gewünschte Servicelevel gegen Bestandskosten abwägen.'],
 ['lagerhaltung','Ein Lager enthält mehrere Jahre alte Normteile, die kaum noch verwendet werden. Welche Datengrundlage ist vor einer Ausbuchung nötig, damit offene Bedarfe und Verwertungsmöglichkeiten nicht übersehen werden?','Umschlag, Bedarf, Verwendbarkeit und mögliche Verwertung der Altbestände prüfen.',['Altbestand pauschal als aktuellen Bedarf behandeln.','Den Lagerbestand abschreiben lassen und erst danach prüfen, ob einzelne Normteile für offene Aufträge noch verwendbar sind.','Die Bestandsdaten löschen, um die Lagerquote zu verbessern.'],'Langsamdreher können gebundenes Kapital und Veralterungsrisiko anzeigen; ihre Behandlung braucht Bedarfsklärung.','Bestände werden realistischer geplant und unnötige Nachkäufe können vermieden werden.'],
 ['lagerorganisation','Mitarbeitende suchen regelmäßig lange nach Werkzeugen, obwohl diese laut System vorhanden sind. Welche Maßnahme ist passend?','Lagerplätze eindeutig kennzeichnen und Entnahme- sowie Rückbuchungsprozess vereinheitlichen.',['Mehr Werkzeuge bestellen, ohne den Verbleib zu klären.','Werkzeuge ohne Lagerplatzkennzeichnung verteilen.','Bestände nur einmal jährlich auswerten.'],'Transparente Lagerorte und Bewegungen verbessern Auffindbarkeit und Bestandsgenauigkeit.','Suchzeiten und unnötige Ersatzbeschaffungen sinken.'],
 ['wareneingang','Eine Lieferung enthält mehr Teile als im Lieferschein angegeben. Wie sollte der Wareneingang vorgehen?','Menge dokumentieren, Abweichung klären und Bestand erst nach geprüftem Beleg freigeben.',['Die Übermenge ohne Nachweis einlagern.','Den Lieferschein eigenmächtig ändern und Rechnung akzeptieren.','Die gesamte Lieferung ablehnen, ohne Vertrag oder Bedarf zu prüfen.'],'Abweichungen müssen nachvollziehbar geklärt werden, bevor Bestand und Zahlungsvorgang fortgeführt werden.','Buchbestand und Lieferantenabrechnung bleiben verlässlich und prüfbar.'],
 ['qualitaetspruefung','Der Prüfplan verlangt bei jedem möglichen Materialfehler die Sperrung der betroffenen Charge und eine Freigabeentscheidung der Qualitätsverantwortlichen. Bei einer Stichprobe fällt ein Teil auf. Was ist zu tun?','Betroffene Charge separieren, Befund dokumentieren und Freigabe nach Prüfregel klären.',['Die gesamte Charge ohne Bewertung direkt in die Produktion geben.','Den Fehler nur mündlich weitergeben und Ware freigeben.','Die übrige Charge anhand einer selbst gewählten Zusatzstichprobe freigeben, ohne den im Prüfplan festgelegten Annahmeumfang zu beachten.'],'Eine kontrollierte Sperrung verhindert, dass ungeklärtes Material unbemerkt weiterverarbeitet wird.','Fehlerkosten und Sicherheitsrisiken können begrenzt werden, während die Lieferantenklärung läuft.'],
 ['materialfluss','Werkstoffe werden mehrfach zwischen Lager und Fertigung umgelagert, bevor sie bearbeitet werden. Wie kann der Materialfluss verbessert werden?','Weg, Übergaben und Bereitstellungspunkte aufnehmen und unnötige Transporte reduzieren.',['Eine weitere Zwischenlagerfläche einrichten, ohne Prozessanalyse.','Alle Werkstoffe unabhängig von Reihenfolge direkt an Maschinen stellen.','Transportzeiten aus der Prozessbetrachtung streichen.'],'Eine Flussanalyse identifiziert unnötige Bewegungen und mögliche Bereitstellungsänderungen.','Durchlaufzeiten und Handhabungsaufwand können sinken, ohne Materialverfügbarkeit zu gefährden.'],
 ['produktionslogistik','Ein Auftrag beginnt an der CNC, obwohl ein erforderliches Werkzeug noch nicht bereitgestellt wurde. Welche Planungsschnittstelle fehlt?','Arbeitsvorbereitung, Werkzeugbereitstellung und Fertigungsfreigabe müssen zeitlich abgestimmt werden.',['Die Maschine früher starten, um Wartezeit auszugleichen.','Das Werkzeug erst nach Beginn des Auftrags suchen.','Werkzeugverfügbarkeit im Auftrag nicht erfassen.'],'Fertigungsstart setzt voraus, dass notwendige Ressourcen bereitstehen.','Maschinenstillstand durch vermeidbare Such- und Wartezeiten nimmt ab.'],
 ['kommissionierung','Ein Versandmitarbeiter packt versehentlich Teile aus zwei Kundenaufträgen zusammen. Welche Prozesskontrolle ist hilfreich?','Kommissionierung auftragsbezogen kennzeichnen und vor Verpackungsabschluss abgleichen.',['Alle fertigen Teile gemeinsam ohne Auftragstrennung lagern.','Den Versandbeleg erst nach Auslieferung erstellen.','Kundenkennzeichnung durch allgemeine Teilecodes ersetzen.'],'Auftragsbezogene Kennzeichnung und Kontrolle verhindern Verwechslungen.','Falschlieferungen und daraus entstehende Rücktransport- und Nacharbeitskosten sinken.'],
 ['lieferplanung','Ein Kunde benötigt eine Teillieferung früher als den Rest des Auftrags. Was sollte die Logistik vor Zusage prüfen?','Verfügbarkeit, zusätzliche Transportkosten, Folgen für Restlieferung und Kundenbedarf abstimmen.',['Die Teillieferung als kostenlos und folgenlos behandeln.','Den Gesamtauftrag ohne Kundeninformation aufteilen.','Nur den frühesten möglichen Termin betrachten.'],'Teillieferung verändert Materialfluss und Kosten und muss mit Bedarf und Auftrag abgestimmt werden.','Der Betrieb kann Kundenservice bieten, ohne Restauftrag und Logistikaufwand zu übersehen.'],
 ['inventur','Bei einer physischen Zählung liegt der gezählte Bestand über dem negativen Systembestand; Wareneingänge und Entnahmen sind noch nicht vollständig gebucht. Welche Prüfung muss vor einer Bestandskorrektur erfolgen, solange Materialbewegungen noch ungebucht sind?','Bewegungsbelege und Buchungszeitpunkte prüfen, Ursache klären und Korrektur dokumentieren.',['Den gezählten Bestand sofort als verfügbaren Bestand buchen und offene Bewegungen nach der Inventurkorrektur nachtragen.','Die Bestandsdifferenz als Ausschuss buchen und die nicht abgeglichenen Materialbelege bei der nächsten Monatsinventur prüfen.','Die Zählung wiederholen und bis dahin den Systembestand als Dispositionsgrundlage weiterverwenden.'],'Negative Bestände deuten häufig auf fehlende oder verspätete Bewegungsbuchungen hin.','Bestandsdaten und Materialverbrauch werden nachvollziehbarer und künftige Disposition verbessert.'],
 ['lagerkennzahlen','Der Lagerumschlag eines Artikels ist hoch, doch es gab mehrere Produktionsunterbrechungen wegen Fehlteilen. Welche Kennzahl sollte ergänzt werden?','Servicegrad oder Fehlmengenhäufigkeit betrachten.',['Nur die Lagerumschlagshäufigkeit weiter erhöhen.','Fehlmengen aus der Kennzahl ausblenden.','Den Lagerwert als Maß für Termintreue verwenden.'],'Hoher Umschlag ist nicht automatisch gut, wenn die Versorgung der Produktion leidet.','Bestandsziele können Kapitalbindung und Lieferfähigkeit balancieren.'],
 ['wertschoepfungskette','Eine Kundenänderung erreicht die Konstruktion, aber nicht Einkauf und Fertigung. Welche Logistikperspektive hilft?','Informations- und Materialübergaben entlang der gesamten Wertschöpfungskette betrachten.',['Jede Abteilung nur nach ihrer lokalen Bearbeitungszeit optimieren.','Kundenänderungen ausschließlich im Vertrieb dokumentieren.','Die Lieferkette auf den physischen Transport begrenzen.'],'Wertschöpfung erfordert abgestimmte Informationsflüsse zwischen den Beteiligten.','Änderungen können früher in Materialbestellung und Produktion berücksichtigt werden.'],
 ['lieferantenbeziehung','Ein Lieferant kündigt für ein auftragskritisches Bauteil eine Verzögerung an. Die Betriebsleitung erwägt Mehrarbeit, hat aber Kapazität und Zusatzkosten noch nicht ermittelt. Was muss vor einer verbindlichen Mehrarbeits- oder Terminzusage vorliegen?','Verfügbare Kapazität und benötigte Mehrarbeitsstunden je betroffenem Auftrag prüfen, Zusatzkosten und Terminwirkung vergleichen und erst danach einen machbaren Kundentermin verbindlich abstimmen.',['Die Information ignorieren, solange Fälligkeit noch nicht überschritten ist.','Sofort alle Bestellungen ohne Prüfung stornieren.','Dem Kunden weiterhin den alten Termin garantieren.'],'Vor einer verbindlichen Zusage müssen Kapazität, Mehrarbeitskosten und Auswirkungen auf betroffene Liefertermine geprüft werden; erst dann lässt sich mit dem Kunden ein belastbarer Termin vereinbaren.','Die Betriebsleitung kann eine machbare und wirtschaftliche Reaktion wählen und Kunden auf Basis eines belastbaren Termins informieren.'],
 ['beschaffungsrecht','Eine Bestellung enthält abweichende Lieferbedingungen in Auftragsbestätigung und Angebot. Was sollte der Einkauf vor weiterer Abwicklung tun?','Dokumente vergleichen, Abweichung klären und vereinbarte Bedingungen nachvollziehbar bestätigen.',['Die jeweils günstigere Klausel stillschweigend auswählen.','Die Abweichung ignorieren und Ware bestellen.','Rechtliche Wirkung ohne Prüfung als eindeutig annehmen.'],'Abweichende Vertragsdokumente können unterschiedliche Rechte und Pflichten abbilden; Klärung ist erforderlich.','Der Betrieb reduziert Streit über Lieferzeit, Preis oder Gefahrübergang.'],
 ['rationalisierung','Ein Lagerbereich wird häufig überfüllt, während ein anderer kaum genutzt wird. Welche Rationalisierungsmaßnahme ist sinnvoll?','Artikelprofile und Bewegungsmuster erfassen und Lagerplätze bedarfsgerecht neu zuordnen.',['Alle Regale entfernen und Ware direkt im Gang abstellen.','Lagerfläche unabhängig von Nutzung weiter anmieten.','Die Bestandsmenge als einzige Ursache festlegen.'],'Platz- und Bewegungsdaten zeigen, ob Layout oder Bestandsstruktur verbessert werden kann.','Such- und Transportwege können kürzer werden und Flächen besser genutzt werden.'],
 ['rationalisierung','Mitarbeitende erfassen Wareneingänge doppelt in zwei Systemen. Welche Verbesserung sollte vor einer Automatisierung geprüft werden?','Datenquelle und Prozessverantwortung vereinheitlichen und doppelte Erfassung beseitigen.',['Doppelte Eingabe automatisiert parallel fortführen.','Ein System ohne Datenabgleich abschalten.','Mehr Pflichtfelder hinzufügen, ohne den Zweck zu klären.'],'Automatisierung eines unnötigen Doppelschritts festigt lediglich die Verschwendung.','Bearbeitungsaufwand und Übertragungsfehler können verringert werden.'],
 ['transportplanung','Ein Spediteur bündelt Sendungen; dadurch wird ein dringender Auftrag einen Tag später zugestellt. Was ist bei der Tourenplanung abzuwägen?','Transportauslastung mit zugesagten Lieferterminen und Dringlichkeit der Sendungen abstimmen.',['Maximale Bündelung unabhängig von Kundenvereinbarungen priorisieren.','Jede Sendung einzeln fahren lassen, ohne Kostenwirkung zu prüfen.','Transportzeit aus der Lieferplanung entfernen.'],'Auslastungsvorteile müssen gegen Service- und Terminfolgen bewertet werden.','Die Versandplanung kann Kosten senken, ohne kritische Lieferzusagen zu verletzen.'],
 ['verpackung','Teile kommen beim Kunden wegen unzureichender Verpackung beschädigt an. Welche Logistikmaßnahme adressiert das Problem?','Verpackungsanforderungen, Schutz und Handhabung für Transportweg und Produkt prüfen.',['Den Spediteur verantwortlich machen, ohne Schadensursache zu untersuchen.','Mehr Verpackungsmaterial unabhängig von Produkt und Transportweg nutzen.','Beschädigungen nur beim Kunden erfassen.'],'Verpackung muss zum Produkt und zu den tatsächlichen Transportbelastungen passen.','Transportschäden und Reklamationen können sinken, während Materialverbrauch gezielt bleibt.'],
 ['retourenlogistik','Ein Kunde sendet ein falsches Bauteil zurück, das möglicherweise wiederverwendbar ist. Wie sollte es behandelt werden?','Retoure identifizieren, Zustand prüfen und nach dokumentierter Freigabe Bestand oder Sperrbestand zuordnen.',['Rücksendung sofort als verfügbaren Neuzugang buchen.','Ware ohne Befund entsorgen.','Die Retoure dem Lagerbestand eines anderen Artikels zuschlagen.'],'Eine kontrollierte Rückführung verhindert fehlerhafte Bestände und erhält die Möglichkeit der Verwertung.','Der Betrieb kann Rücksendekosten und nutzbare Materialien transparent behandeln.'],
 ['lagerlayout','Schwere Werkstücke werden in hohen Regalen über häufig genutzten leichten Teilen gelagert. Welche Layoutprüfung ist nötig?','Gewicht, Zugriffshäufigkeit, Transportmittel und sichere Greifhöhen berücksichtigen.',['Lagerplätze ausschließlich alphabetisch anordnen.','Schwere Teile unabhängig von Handhabung oben belassen.','Zugriffshäufigkeit bei der Lagerplanung ignorieren.'],'Lagerlayout muss Bewegungs- und Sicherheitsanforderungen berücksichtigen.','Umlagerungen und Handhabungsrisiken sinken; häufig benötigte Teile sind besser erreichbar.'],
 ['bedarfsvorschau','Ein Großkunde kündigt einen einmaligen Sonderbedarf an, der den üblichen Verbrauch stark übersteigt. Wie sollte die Disposition reagieren?','Sonderbedarf getrennt kennzeichnen und nicht ungeprüft in den permanenten Verbrauchstrend übernehmen.',['Den Spitzenbedarf als neuen monatlichen Normalverbrauch fortschreiben.','Sonderbedarf vollständig ignorieren.','Dauerhafte Bestellparameter auf Basis des Einzelereignisses erhöhen.'],'Einmalige Nachfrage muss von wiederkehrendem Bedarf unterschieden werden.','Nachbestellungen bleiben nach dem Sonderauftrag angemessen und Überbestände werden vermieden.']
]});
areas[2].items.push(
 ['bestandsplanung','Ein Rohmaterial hat ein kurzes Verfalls- oder Alterungsrisiko und wird selten verbraucht. Wie sollte der Betrieb seine Bestellpolitik gestalten?','Bedarf, Mindestlosgröße und Haltbarkeit abstimmen und Überbestände vermeiden.',['Den größten Mengenrabatt unabhängig von Haltbarkeit wählen.','Die Ware nach Eingang ohne Verbrauchsplanung lagern.','Das Alterungsrisiko nur bei der Inventur erfassen.'],'Die Bestellmenge muss neben Preis auch Nutzbarkeit innerhalb der Haltbarkeit berücksichtigen.','Abschreibungen und Ausschuss durch unbrauchbar gewordene Materialien werden unwahrscheinlicher.'],
 ['lieferantenbewertung','Ein Lieferant erfüllt Preis- und Qualitätserwartung, meldet aber Änderungen häufig verspätet. Welche Bewertung ist sinnvoll?','Kommunikation und Änderungsmanagement als Teil der Lieferantenleistung bewerten.',['Die Zusammenarbeit nur nach Stückpreis einstufen.','Informationsverhalten als nicht-logistisch behandeln.','Den Lieferanten ohne Rückmeldung sofort sperren.'],'Frühzeitige Information ist für Disposition und Kundenliefertermine relevant.','Risiken aus späten Änderungsmeldungen können in Lieferantenentwicklung oder Alternativen einfließen.'],
 ['beschaffungsrisiko','Ein Werkstoff stammt aus einer Region mit zunehmenden Transportstörungen. Was ist eine angemessene Vorsorge?','Abhängigkeit, Wiederbeschaffungszeit und alternative Bezugswege bewerten.',['Den Bestand ohne Risikoprüfung maximal erhöhen.','Den Kunden eine Liefergarantie ohne Absicherung geben.','Das Risiko erst nach einer ausgebliebenen Lieferung dokumentieren.'],'Die Vorsorge sollte proportional zum Risiko sein und mögliche Alternativen einbeziehen.','Der Betrieb kann Versorgungssicherheit und Kapitalbindung bewusst austarieren.'],
 ['disposition','Das ERP schlägt eine Bestellung vor, obwohl ausreichend Bestand vorhanden ist; mehrere Entnahmen wurden noch nicht gebucht. Was ist zuerst zu prüfen?','Buchungsrückstand und tatsächliche Verfügbarkeit mit Lager und Fertigung abgleichen.',['Vorschlag automatisch freigeben.','Den Systembestand ohne Zählung überschreiben.','Die vorgeschlagene Menge bestellen und Buchungsfehler ignorieren.'],'Disposition ist nur so gut wie die zugrundeliegenden Bestandsdaten.','Fehlbestellungen werden vermieden und der Lagerprozess kann gezielt korrigiert werden.'],
 ['lagerzonierung','Kleinteile und große Werkstücke werden im selben Bereich gelagert, was die Kommissionierung verlangsamt. Was sollte bei einer Neuordnung berücksichtigt werden?','Abmessungen, Umschlag, Zugriffshäufigkeit und geeignete Lagertechnik gruppieren.',['Alle Artikel nach alphabetischer Reihenfolge über dieselben Regale verteilen.','Umschlagshäufigkeit bei der Platzwahl ausblenden.','Nur die Entfernung zum Wareneingang als Kriterium verwenden.'],'Eine auf Artikelprofil und Zugriff abgestimmte Zonierung reduziert Handhabungsaufwand.','Kommissionierung und Flächennutzung werden effizienter, ohne Sicherheitsanforderungen zu vernachlässigen.'],
 ['materialbereitstellung','Die Fertigung ruft Material häufig kurzfristig aus dem Zentrallager ab, obwohl der Tagesplan bekannt ist. Welche Lösung könnte den Fluss verbessern?','Material anhand freigegebener Aufträge rechtzeitig und mengenrichtig an definierte Bereitstellplätze liefern.',['Alle Aufträge ohne Reihenfolge gleichzeitig an Maschinen stellen.','Material erst nach Maschinenstillstand aus dem Lager holen.','Die Bereitstellung aus dem Produktionsplan entfernen.'],'Vorausgeplante Bereitstellung nutzt verfügbare Informationen und verringert Ad-hoc-Unterbrechungen.','Maschinenbedienende verbringen weniger Zeit mit Materialsuche.'],
 ['produktionssteuerung','Ein dringender Auftrag wird in die Fertigungsreihenfolge eingeschoben und verdrängt mehrere zugesagte Termine. Was muss die Produktionslogistik vor der Umpriorisierung tun?','Auswirkungen auf Kapazität, Materialverfügbarkeit und betroffene Liefertermine transparent machen.',['Nur die Dringlichkeit des neuen Auftrags betrachten.','Alle anderen Kundenaufträge ohne Information verschieben.','Den Auftrag zusätzlich einplanen, ohne Kapazitätsprüfung.'],'Priorisierung hat Folgen für bestehende Aufträge und muss mit Ressourcen und Kundenverpflichtungen abgestimmt werden.','Terminänderungen und Engpasswirkungen werden sichtbar, bevor die Werkstatt umplant.'],
 ['kommissionierung','Die Versandkontrolle findet regelmäßig fehlende Kleinteile in ansonsten vollständigen Aufträgen. Welche Maßnahme verbessert die Fehlererkennung?','Auftragsbezogene Packliste mit Scan- oder Mengenabgleich vor Versand einsetzen.',['Nur die äußere Verpackung auf Beschädigungen prüfen.','Alle Kleinteile lose und ohne Zählung beilegen.','Den Packvorgang nach dem Versand dokumentieren.'],'Ein systematischer Mengenabgleich erkennt fehlende Positionen vor der Auslieferung.','Nachsendungen und Kundenbeschwerden können reduziert werden.'],
 ['lieferperformance','Die Liefertermintreue ist hoch, aber viele Aufträge werden mit teuren Sonderfahrten pünktlich. Was sagt die Kennzahl allein nicht?','Sie zeigt nicht die Kosten und Prozessaufwände, die zur Terminerfüllung erforderlich waren.',['Sie beweist, dass die Logistikkosten minimal sind.','Sie enthält automatisch den Bestandumschlag.','Sie zeigt die Lieferqualität nach Kundeneinsatz.'],'Eine einzelne Servicekennzahl bildet den Ressourceneinsatz nicht ab.','Das Management kann Termintreue mit Kosten- und Planungsstabilität gemeinsam optimieren.'],
 ['inventur','Ein hochwertiges Werkzeug ist laut System an einem Lagerplatz, dort aber nicht auffindbar. Welche Reaktion ist angemessen?','Letzte Bewegungen und Zugriffe prüfen, Suche dokumentieren und Bestand nach Verfahren klären.',['Den Artikel direkt als gestohlen melden, ohne Belege zu prüfen.','Einen neuen Artikel bestellen und alten Bestand unverändert führen.','Den Bestand durch einen anderen Werkzeugtyp ersetzen.'],'Nachvollziehbare Ursachenklärung unterscheidet Buchungsfehler, Umlagerung und tatsächlichen Verlust.','Bestandsgenauigkeit verbessert sich und unnötige Ersatzkosten werden vermieden.'],
 ['lieferantenrecht','Eine angelieferte Charge weicht von der vereinbarten Spezifikation ab. Was sollte der Betrieb für eine belastbare weitere Behandlung tun?','Abweichung und Charge dokumentieren, Ware prüfen und vereinbarte Reklamations- beziehungsweise Prüfabläufe beachten.',['Material trotz Abweichung ohne Prüfung verarbeiten.','Ware kommentarlos entsorgen und Rechnung ignorieren.','Rechtsfolgen pauschal annehmen, ohne Vertrag und Sachverhalt zu prüfen.'],'Dokumentation und vertraglich abgestimmtes Vorgehen sichern eine sachgerechte Qualitäts- und Anspruchsklärung.','Der Betrieb begrenzt Produktionsrisiken und kann mit dem Lieferanten auf Faktenbasis klären.'],
 ['rationalisierung','Ein hoher Anteil der Lagerbewegungen besteht aus mehrfacher Umlagerung desselben Materials. Welcher Schritt ist zuerst sinnvoll?','Bewegungsdaten und Layout analysieren, um vermeidbare Umlagerungsursachen zu finden.',['Eine weitere Umlagerungsschicht einführen.','Alle Umlagerungen pauschal als produktiv bewerten.','Den Bestand reduzieren, ohne Materialfluss zu prüfen.'],'Die Ursache kann in Layout, Bereitstellung oder Platzplanung liegen und sollte vor einer Maßnahme ermittelt werden.','Interne Transportkosten und Beschädigungsrisiken können gezielt reduziert werden.'],
 ['logistikkennzahlen','Das Lager bindet weniger Kapital, doch Produktionsstillstände durch Fehlteile nehmen zu. Wie sollte das Zielsystem angepasst werden?','Bestandswert mit Fehlmengen, Servicegrad und Stillstandsfolgen gemeinsam steuern.',['Den Lagerwert weiter minimieren, unabhängig von Produktionswirkung.','Fehlteile als Fertigungsproblem aus der Logistikbewertung entfernen.','Sicherheitsbestände für alle Teile identisch festlegen.'],'Kapitalbindung und Versorgungssicherheit stehen in einem Zielkonflikt.','Die Disposition kann differenzierte Bestandsziele für kritische und unkritische Materialien setzen.'],
 ['wertschoepfungskette','Ein Kunde ändert eine Zeichnung, nachdem der Betrieb das Material bereits bestellt hat. Welche Koordination ist erforderlich?','Änderungsinformation, vorhandene Beschaffung und Fertigungsfolgen gemeinsam bewerten.',['Die Änderung nur an die Konstruktion weiterleiten.','Alte Bestellung und neue Zeichnung unabhängig weiterführen.','Material erst nach Fertigstellung des Auftrags prüfen.'],'Änderungen wirken entlang der Kette auf Material, Kosten und Ablauf.','Ausschuss und vermeidbare Kosten können vor der Weiterverarbeitung begrenzt werden.'],
 ['lagerkosten','Ein Unternehmen mietet kurzfristig zusätzlichen Lagerraum für langsam drehende Bestände. Welche Frage sollte es zuerst beantworten?','Ob Bestandsursache, Abbauoption und Gesamtkosten die zusätzliche Fläche rechtfertigen.',['Zusätzliche Lagerfläche als kostenneutral betrachten.','Mietkosten allein dem Umsatz zurechnen.','Alle langsam drehenden Teile ohne Verwendungsprüfung entsorgen.'],'Flächenkosten lösen die Bestandsursache nicht; Nutzen und Alternativen gehören in den Vergleich.','Das Unternehmen kann unnötige laufende Kosten vermeiden und Kapitalbindung reduzieren.'],
 ['transportkosten','Ein Kunde wünscht eine Expresslieferung, deren Mehrkosten den Auftragsbeitrag stark reduzieren. Was ist vor Zusage zu klären?','Mehrkosten, Zahlungsbereitschaft und vertragliche Lieferzusage abstimmen.',['Expressversand automatisch als kostenlose Standardleistung behandeln.','Den Versand nach Auftragsschluss ohne Kundenvereinbarung berechnen.','Nur die Dauer des Transports betrachten.'],'Transportservice verändert Aufwand und wirtschaftliche Bedingungen des Auftrags.','Die Vertriebsentscheidung kann Kundennutzen und Marge in Einklang bringen.'],
 ['gefahrgutbewusstsein','Ein Werkstoff weist auf dem Sicherheitsdatenblatt besondere Handhabungshinweise auf. Was muss die Logistik vor Einlagerung tun?','Kennzeichnung, Lagerbedingungen und geltende betriebliche Schutzvorgaben prüfen.',['Das Sicherheitsdatenblatt nur im Einkauf archivieren.','Den Werkstoff mit allen Materialien zusammenlagern.','Lagerbedingungen ausschließlich nach verfügbarer Fläche wählen.'],'Sicherheits- und Lageranforderungen müssen vor der physischen Einlagerung berücksichtigt werden.','Gesundheits-, Sach- und Betriebsrisiken werden frühzeitig in der Lagerorganisation berücksichtigt.'],
 ['wareneingang','Eine Lieferung kommt außerhalb der vereinbarten Annahmezeit und niemand ist für die Prüfung verfügbar. Welche Prozessvorsorge ist hilfreich?','Annahmefenster und Vertretungsregel für kritische Lieferungen planen.',['Ware ungeprüft im Außenbereich abstellen.','Lieferantenzusage als Ersatz für Wareneingangskontrolle verwenden.','Den Wareneingang ohne Dokumentation buchen.'],'Ein abgestimmter Annahmeprozess sichert Prüfung, Dokumentation und korrekte Lagerung.','Beschädigung, Fehlmengen und ungeklärte Bestandszugänge werden weniger wahrscheinlich.'],
 ['versandplanung','Mehrere Aufträge sind fertig, aber ein gemeinsames Transportmittel hat begrenzte Kapazität. Wie sollte die Ladung priorisiert werden?','Liefertermine, Kundenrelevanz, Ladungssicherung und wirtschaftliche Bündelung berücksichtigen.',['Nur die räumlich nächstgelegenen Kunden bedienen.','Sendungen ohne Prüfung der Ladungssicherung maximieren.','Versand nach Auftragswert allein ordnen.'],'Eine belastbare Versandpriorität berücksichtigt Termine, Transportfähigkeit und Kundenfolgen.','Die knappe Transportkapazität wird transparent und risikoarm genutzt.'],
 ['bestandsklassifizierung','Einige wenige Artikel verursachen den größten Teil des Bestandswerts. Welche Analyse kann die Überwachung priorisieren?','Wertanteile klassifizieren und Kontrollintensität risikoorientiert festlegen.',['Alle Artikel unabhängig von Wert und Kritikalität gleich häufig prüfen.','Nur günstige Artikel überwachen.','Die wertvollsten Artikel ohne Zählung ausgeben.'],'Eine wertbezogene Klassifizierung unterstützt abgestufte Kontrolle, ersetzt aber keine Kritikalitätsprüfung.','Kontrollaufwand kann auf wirtschaftlich bedeutende Bestände konzentriert werden.'],
 ['lieferantenentwicklung','Ein Lieferant weist wiederholt schwankende Maßqualität auf, ist aber strategisch wichtig. Welche Maßnahme kann die Zusammenarbeit verbessern?','Ursachen- und Verbesserungsplan mit Qualitätsdaten, Verantwortlichen und Überprüfung vereinbaren.',['Lieferant sofort ohne Beleg dauerhaft ausschließen.','Qualitätsmängel akzeptieren, um die Beziehung zu erhalten.','Fehlerdaten nicht teilen.'],'Gemeinsame Ursachenarbeit ermöglicht Verbesserung und erhält zugleich klare Qualitätsanforderungen.','Fehlerquoten können sinken, ohne dass die Versorgung abrupt gefährdet wird.'],
 ['materialidentifikation','Ähnliche Werkstoffe liegen in unbeschrifteten Behältern; Verwechslungen sind möglich. Was ist die dringendste Prozessverbesserung?','Eindeutige Identifikation, Chargen- oder Artikelkennzeichnung und getrennte Lagerplätze sicherstellen.',['Material nach Farbe unterscheiden.','Behälter ohne Kennzeichnung nach Lagerort erinnern.','Werkstoffe ungeprüft an die Fertigung ausgeben.'],'Eindeutige Kennzeichnung ist Voraussetzung für sichere Auswahl und Rückverfolgbarkeit.','Falsche Materialverwendung und spätere Ursachenunklarheit werden reduziert.'],
 ['lieferketteninformation','Der Vertrieb erhält von einem Kunden eine Nachfrageänderung, die Einkauf erst Wochen später erfährt. Welche Informationsregel hilft?','Relevante Nachfrageänderungen zeitnah an Disposition und Einkauf übermitteln.',['Kundendaten nur in der Vertriebsabteilung halten.','Einkauf ausschließlich anhand vergangener Verbrauchswerte planen lassen.','Änderungen erst am Jahresende zusammenfassen.'],'Frühzeitige Informationsweitergabe erlaubt Anpassung von Bedarf und Bestellungen.','Überbestände und Fehlmengen aus veralteten Bedarfssignalen werden geringer.'],
 ['lagerlayout','Der Wareneingang kreuzt häufig den Weg der fertigen Versandaufträge. Welche Analyse unterstützt eine sichere Umgestaltung?','Materialwege, Kreuzungspunkte, Verkehrsregeln und Flächenbedarf aufnehmen.',['Nur die Anzahl der Regale zählen.','Transportwege verkürzen, ohne Verkehrsrisiken zu betrachten.','Den Versandbereich verkleinern, bevor Mengen analysiert sind.'],'Layoutplanung muss Effizienz und sichere Verkehrsführung gemeinsam berücksichtigen.','Kollisionen und unnötige Wege können sinken, während Arbeitsabläufe klarer werden.'],
 ['nachhaltige_logistik','Ein Lieferant verpackt jede Kleinteillieferung einzeln, wodurch viel Verpackungsabfall entsteht. Was kann der Einkauf prüfen?','Wiederverwendbare oder gebündelte Verpackungslösungen unter Qualitäts- und Transportanforderungen bewerten.',['Verpackung ersatzlos abschaffen, unabhängig vom Produktschutz.','Abfallmenge ignorieren, solange Material pünktlich ankommt.','Alle Teile in einer unsortierten Großkiste liefern lassen.'],'Verpackungslösungen müssen Abfall reduzieren und zugleich Schutz sowie Identifikation sichern.','Materialschäden und Entsorgungsaufwand können gleichzeitig berücksichtigt werden.'],
 ['logistiksteuerung','Ein Auftrag ist fertig, bleibt aber wegen fehlender Versanddokumentation im Lager. Welche Kennzahl oder Prozesskontrolle kann den Engpass sichtbar machen?','Zeit zwischen Fertigmeldung, Dokumentenfreigabe und tatsächlichem Versand messen.',['Nur die Produktionszeit erfassen.','Versandverzögerungen dem Kunden zurechnen.','Bestand nach Fertigmeldung aus dem System löschen.'],'Eine Durchlaufzeitmessung an der Schnittstelle zeigt, wo der fertige Auftrag wartet.','Dokumenten- und Versandabläufe lassen sich gezielt verbessern und Lagerliegezeiten senken.']
);
areas.push({id:'hsq-marketing-vertrieb',name:'Marketing und Vertrieb',paragraph:4,items:[
 ['marketingplanung','Die Anfragezahlen steigen, doch viele Interessenten passen nicht zur Fertigungsausstattung. Welcher Marketingplanungsschritt ist sinnvoll?','Zielkundensegmente und deren Anforderungen mit den eigenen Leistungsmerkmalen abgleichen.',['Alle Anfragen unabhängig von Passung als Zielgruppe behandeln.','Werbebudget allein nach Klickzahlen erhöhen.','Die Fertigungsausstattung in der Marktanalyse ignorieren.'],'Eine passende Zielgruppe erhöht die Chance, dass Marketingkontakte zu erfüllbaren Aufträgen werden.','Vertrieb kann Aufwand auf Segmente richten, die der Betrieb profitabel bedienen kann.'],
 ['marktforschung','Ein neuer Wettbewerber bietet günstigere Standardteile an; unklar ist, ob die eigenen Kunden vergleichbare Leistungen sehen. Wie sollte der Betrieb vorgehen?','Kundenanforderungen, Vergleichsprodukte und Entscheidungskriterien gezielt erheben.',['Preise sofort senken, ohne Vergleichbarkeit zu prüfen.','Kundenmeinungen durch interne Vermutungen ersetzen.','Nur den Webauftritt des Wettbewerbers beobachten.'],'Marktforschung klärt, ob Angebote tatsächlich vergleichbar sind und worauf Kunden Wert legen.','Preisentscheidungen können an echtem Kundennutzen statt an Vermutungen ausgerichtet werden.'],
 ['segmentierung','Großkunden verlangen Rahmenplanung, während kleine Werkstätten kurzfristige Einzelteile benötigen. Was ermöglicht eine Segmentierung?','Angebote und Kommunikationswege an die unterschiedlichen Bedarfsmuster anpassen.',['Allen Kunden identische Konditionen und Lieferprozesse anbieten.','Kunden ausschließlich nach Unternehmensnamen gruppieren.','Die kleinere Kundengruppe aus der Analyse entfernen.'],'Bedarfsspezifische Segmente helfen, passende Leistungen und Prozesse zu gestalten.','Vertrieb kann Serviceaufwand und Angebotsform an Kundennutzen ausrichten.'],
 ['positionierung','Ein kleiner Zulieferer kann keine Preisführerschaft beanspruchen, reagiert aber sehr flexibel auf Sonderwünsche. Wie sollte er sich positionieren?','Flexibilität als belegbares Nutzenversprechen für passende Kundengruppen herausstellen.',['Die niedrigsten Preise behaupten, ohne die Kosten zu prüfen.','Alle möglichen Wettbewerbsvorteile gleichzeitig versprechen.','Die eigene Stärke nicht kommunizieren.'],'Eine glaubwürdige Positionierung knüpft an tatsächliche Fähigkeiten an.','Kunden mit Bedarf an flexibler Fertigung erkennen den Mehrwert und Preisvergleiche werden sachgerechter.'],
 ['marketingmix','Ein technisches Servicepaket wird selten gebucht, obwohl Kunden Stillstandsrisiken nennen. Welche Maßnahme prüft direkt, ob die angebotenen Serviceleistungen den von Kunden genannten Stillstandsrisiken entsprechen?','Mit Kunden, die Stillstandsrisiken genannt haben, strukturierte Bedarfsgespräche zu Nutzen und Leistungsumfang führen.',['Die Angebotsdarstellung anhand häufiger Rückfragen überarbeiten und den Leistungsumfang unverändert lassen.','Bisherige Angebotskonversion und Preisnachlässe auswerten, ohne Kunden nach den benötigten Serviceleistungen zu fragen.','Den Preis als Qualitätsindikator testen und die Reaktion der Kunden vor einer Überarbeitung des Leistungsumfangs beobachten.'],'Die Elemente des Marketingmix müssen zum Bedarf und zur Wahrnehmung der Kunden passen.','Ein passendes Angebot kann besser verständlich und erreichbar werden.'],
 ['produktpolitik','Kunden fragen zunehmend nach dokumentierter Qualitätsprüfung zu Einzelteilen. Welche Produktpolitikoption sollte geprüft werden?','Prüfdokumentation als klar abgegrenzte Zusatzleistung oder Leistungsmerkmal gestalten.',['Die Dokumentation ohne Kostenprüfung für jeden Auftrag zusagen.','Die Kundenanforderung als reine Preisfrage behandeln.','Die Prüfprozesse unverändert lassen und den Nutzen behaupten.'],'Eine Zusatzleistung sollte konkret definiert und auf Aufwand sowie Kundennutzen geprüft werden.','Der Betrieb kann Leistungen differenzieren und Prüfaufwand in die Kalkulation aufnehmen.'],
 ['preispolitik','Ein Interessent vergleicht das Angebot nur anhand des Stückpreises, obwohl die eigene Lösung kürzere Lieferzeit bietet. Wie kann Vertrieb reagieren?','Gesamtnutzen und relevante Leistungsunterschiede quantifizieren und verständlich darstellen.',['Den Preis sofort unter Wettbewerbsniveau senken.','Lieferzeit als unwichtig erklären.','Nicht vergleichbare Wettbewerbsangebote als identisch behandeln.'],'Preisverhandlungen können den Gesamtwert betrachten, wenn Unterschiede belastbar belegt werden.','Der Betrieb kann Marge eher erhalten, wenn der Kundennutzen tatsächlich relevant ist.'],
 ['vertriebsmanagement','Viele Angebote werden erstellt, aber Vertriebsmitarbeitende verfolgen sie uneinheitlich nach. Welche Prozessverbesserung ist sinnvoll?','Phasen, Verantwortliche und Wiedervorlagezeitpunkte der Pipeline verbindlich definieren.',['Alle offenen Angebote täglich ohne Priorität anrufen.','Verlorene Angebote aus der Pipeline löschen.','Das Angebotsdatum als sicheren Auftragseingang behandeln.'],'Ein standardisierter Prozess erhöht Nachverfolgung und Prognosequalität.','Chancen werden systematisch betreut und Vertriebskapazität besser verteilt.'],
 ['vertriebsmanagement','Ein Kunde erhält von Vertrieb und Technik unterschiedliche Aussagen zum Liefertermin. Welche Maßnahme sollte der Betrieb treffen?','Terminbestätigung aus einer abgestimmten Quelle mit klarer Freigabeverantwortung sicherstellen.',['Beide Angaben dem Kunden gleichzeitig überlassen.','Vertrieb soll Termine ohne Fertigungsabgleich zusagen.','Technische Terminprognosen grundsätzlich ausblenden.'],'Konsistente Zusagen erfordern Abstimmung zwischen Marktversprechen und Kapazitätsplan.','Vertrauen und Lieferplanung werden weniger durch widersprüchliche Zusagen belastet.'],
 ['kundenbindung','Ein langjähriger Kunde bestellt weniger, antwortet aber weiterhin auf Rückfragen. Welche Vorgehensweise ist angemessen?','Im strukturierten Gespräch Bedarf, Zufriedenheit und Veränderungen im Beschaffungsprozess ermitteln.',['Sofort einen pauschalen Rabatt gewähren.','Rückgang als sichere Kündigung werten.','Den Kontakt nur bei neuen Aufträgen aufnehmen.'],'Ein offener Dialog liefert Hinweise auf Ursachen und mögliche passende Lösungen.','Der Betrieb kann Abwanderungsrisiken früher erkennen und Kundenbeziehung gezielt entwickeln.'],
 ['kundenbindung','Eine Reklamation wird innerhalb eines Tages gelöst, aber der Kunde erhält keine Rückmeldung zum Abschluss. Was ist im Serviceprozess zu ergänzen?','Ergebnis und vereinbarte Folgemaßnahme aktiv an den Kunden kommunizieren.',['Den Vorgang intern schließen, sobald ein Ersatzteil versandt ist.','Die Rückmeldung dem Kunden überlassen.','Jede Reklamation mit einem Rabatt beenden.'],'Kunden benötigen Klarheit über Lösung und Prävention, nicht nur interne Bearbeitung.','Transparenz kann Vertrauen und Wiederkaufbereitschaft stärken.'],
 ['marktanalyse','Ein saisonaler Nachfrageanstieg wird als dauerhaftes Marktwachstum interpretiert. Welche Analyse schützt vor Fehlplanung?','Mehrjährige beziehungsweise saisonbereinigte Entwicklung und Marktursachen vergleichen.',['Nur den stärksten Monat annualisieren.','Schwache Saisonmonate aus der Statistik streichen.','Auftragseingang und Nachfrage grundsätzlich gleichsetzen.'],'Saisonalität und struktureller Trend sind verschiedene Effekte.','Kapazitäts- und Lagerplanung beruhen weniger auf vorübergehenden Spitzen.'],
 ['absatzprognose','Ein Großkunde kündigt unverbindlich einen möglichen Folgeauftrag an. Wie sollte der Vertrieb diese Information in der Absatzplanung behandeln?','Wahrscheinlichkeit und Status kenntlich machen und als Szenario statt sicheren Auftrag führen.',['Den gesamten Wert als fest zugesagten Umsatz einplanen.','Die Chance aus der Planung verbannen.','Den Auftrag ohne Angebot als Auftragseingang verbuchen.'],'Unverbindliche Chancen benötigen eine andere Gewichtung als bestätigte Aufträge.','Produktions- und Liquiditätsplanung überhöhen die sichere Nachfrage nicht.'],
 ['werbung','Eine Fachmesse zieht viele Besucher, aber wenige passende B2B-Kontakte an. Welche Auswertung ist für die nächste Messeentscheidung relevant?','Qualifizierte Leads, Kosten, Folgeangebote und gewonnene Aufträge analysieren.',['Nur die Gesamtzahl der Standbesuche messen.','Messekosten ignorieren, weil Sichtbarkeit nicht messbar ist.','Jeden Messekontakt als Kunden zählen.'],'Die Wirkung sollte an Zielgruppe und nachgelagertem Vertriebsergebnis beurteilt werden.','Marketingbudget kann auf Veranstaltungen mit relevanter Reichweite konzentriert werden.'],
 ['distributionspolitik','Ein Kunde in einer entfernten Region benötigt häufige kleine Lieferungen. Welche Distributionsentscheidung sollte geprüft werden?','Transportkosten, Lieferfrequenz und mögliche Bündelung oder regionale Partner vergleichen.',['Jede Lieferung ungeachtet der Kosten als Express versenden.','Lieferfrequenz reduzieren, ohne Kundenbedarf abzustimmen.','Nur den Fertigungsstandort betrachten.'],'Distribution umfasst Zugangs- und Lieferwege und beeinflusst Service sowie Kosten.','Der Betrieb kann Lieferfähigkeit und Logistikaufwand besser in Einklang bringen.'],
 ['angebotsgestaltung','Ein Angebot enthält technische Details, aber der Kunde versteht nicht, welche Leistung im Preis enthalten ist. Was sollte verbessert werden?','Leistungsumfang, Annahmen, Ausschlüsse und optionale Leistungen klar strukturieren.',['Mehr technische Abkürzungen ergänzen.','Nicht enthaltene Leistungen bewusst unerwähnt lassen.','Den Gesamtpreis ohne Leistungsbeschreibung nennen.'],'Klare Angebotsbestandteile reduzieren Missverständnisse und erleichtern den Vergleich.','Nachverhandlungen über Leistungsumfang und unerwartete Zusatzkosten werden seltener.'],
 ['preisverhandlung','Der Kunde bittet um Preisnachlass, kann dafür aber eine größere Losgröße zusagen. Wie sollte Vertrieb den Vorschlag bewerten?','Nachlass gegen tatsächliche Kosten- und Planungsvorteile der größeren Losgröße rechnen.',['Den Rabatt ohne Gegenrechnung sofort geben.','Größere Lose grundsätzlich als kostenneutral behandeln.','Den vereinbarten Preis nach Vertragsannahme einseitig ändern.'],'Eine Gegenleistung kann Kosten senken, muss aber in der konkreten Kalkulation belegt sein.','Preisnachlässe werden eher an messbare Effizienzvorteile gekoppelt.'],
 ['preisstrategie','Die Materialkosten steigen während der Laufzeit eines Angebots, das noch nicht angenommen wurde. Welche Handlung ist angemessen?','Gültigkeitsdauer und Kalkulationsannahmen prüfen und vor Annahme gegebenenfalls ein aktualisiertes Angebot abstimmen.',['Preis unabhängig von Gültigkeitsbedingungen beliebig erhöhen.','Materialkostensteigerung stets allein dem Kunden auferlegen.','Das Angebot trotz abgelaufener Grundlage unverändert als bindend behandeln.'],'Vor Vertragsschluss hängen Preisänderungsmöglichkeiten von Angebotsinhalt und Fristen ab.','Der Betrieb schützt Kalkulation und wahrt zugleich klare Kundenkommunikation.'],
 ['vertragsrecht','Ein Kunde nimmt ein schriftliches Angebot fristgerecht ohne Änderungen an. Was sollte der Vertrieb nach Eingang der Annahme tun?','Auftragsbestätigung und Übergabe an die Ausführung mit vereinbartem Leistungsumfang sicherstellen.',['Den vereinbarten Preis anschließend einseitig neu kalkulieren.','Die Annahme ignorieren, bis der Kunde nochmals anruft.','Zusatzleistungen ohne Vereinbarung in den Auftrag aufnehmen.'],'Eine wirksame Annahme begründet die vereinbarten Bedingungen; Änderungen benötigen eine abgestimmte Grundlage.','Verlässliche Übergabe verhindert Preis- und Leistungsstreit im späteren Auftragsverlauf.'],
 ['internationalisierung','Ein Kunde aus einem anderen Land fordert Angebote in einer fremden Währung. Was sollte Vertrieb in der Kalkulation zusätzlich berücksichtigen?','Währungsrisiko, Zahlungsbedingungen, Lieferkosten und anwendbare Vertragsbedingungen prüfen.',['Den Umrechnungskurs des Angebotstags dauerhaft garantieren.','Internationale Logistikkosten mit Inlandskosten gleichsetzen.','Zahlungs- und Rechtsbedingungen nicht dokumentieren.'],'Grenzüberschreitende Geschäfte können zusätzliche Kosten und Risiken haben, die vor Zusage geklärt werden.','Angebotspreis und Zahlungsplanung bilden die tatsächlichen Rahmenbedingungen besser ab.'],
 ['interkulturelle_kommunikation','In einer Verhandlung werden knappe Antworten des ausländischen Geschäftspartners als Ablehnung verstanden, obwohl die Sachlage unklar ist. Wie sollte das Team reagieren?','Bedeutung durch offene Rückfragen klären und Kommunikationsannahmen nicht vorschnell bewerten.',['Die Verhandlung sofort abbrechen.','Kulturelle Stereotype als sichere Erklärung verwenden.','Die eigene Position wiederholen, ohne Verständnis zu prüfen.'],'Klärende Fragen reduzieren Missverständnisse und vermeiden unbelegte Zuschreibungen.','Verhandlungspartner können Erwartungen und nächste Schritte präziser abstimmen.'],
 ['crm','Kundenkontakte sind in verschiedenen persönlichen Tabellen verteilt; wichtige Absprachen gehen verloren. Welche Vertriebsmaßnahme hilft?','Kundendaten und Kontaktverlauf in einer gepflegten, zugriffsgeregelten Übersicht dokumentieren.',['Alle Tabellen ohne Berechtigungen zusammenführen.','Historische Absprachen nach jedem Auftrag löschen.','Nur persönliche Erinnerung als CRM nutzen.'],'Zentral dokumentiertes und gepflegtes Wissen macht die Kundenbeziehung teamfähig.','Vertretung und konsistente Betreuung werden erleichtert, ohne Datenschutzanforderungen auszublenden.'],
 ['absatzkontrolle','Die Zahl neu gewonnener Kunden steigt, der durchschnittliche Deckungsbeitrag sinkt jedoch. Was sollte Marketing und Vertrieb untersuchen?','Neukundensegmente, Akquisitionskosten, Preise und Auftragsprofitabilität analysieren.',['Kundenzuwachs allein als Erfolg werten.','Niedrigere Beiträge durch mehr Kunden automatisch kompensieren.','Akquisitionskosten nicht den Kundengruppen zuordnen.'],'Wachstum ist nur dann wirtschaftlich, wenn Beitrag und Kosten zusammen betrachtet werden.','Vertrieb kann Kundenakquise auf tragfähige Segmente konzentrieren.'],
 ['sortimentspolitik','Ein selten bestelltes Produkt bindet viel Entwicklungs- und Lageraufwand, wird aber von einem strategischen Kunden benötigt. Wie sollte die Sortimentsentscheidung erfolgen?','Kundenwert, Vollkosten, strategische Bedeutung und alternative Bereitstellung vergleichen.',['Das Produkt ausschließlich nach Absatzmenge streichen.','Es unbegrenzt weiterführen, ohne Aufwand zu erfassen.','Den strategischen Kunden ohne Gespräch kündigen.'],'Eine Sortimentsentscheidung muss quantitative und qualitative Gründe transparent abwägen.','Das Unternehmen kann Kundenbindung und Wirtschaftlichkeit mit geeigneten Sonderkonditionen verbinden.'],
 ['kommunikation','Eine Werbeaussage verspricht eine Lieferzeit, die der Betrieb nur bei freier Kapazität einhalten kann. Was sollte vor Veröffentlichung erfolgen?','Aussage mit Fertigungskapazität und belastbaren Lieferbedingungen abstimmen.',['Die Aussage veröffentlichen und Ausnahmen später erklären.','Die Kapazitätsannahme aus der Planung entfernen.','Eine kürzere Lieferzeit wählen, um Aufmerksamkeit zu erzeugen.'],'Marketingversprechen müssen durch realisierbare Leistung und klare Voraussetzungen gedeckt sein.','Fehlzusagen und Vertrauensverlust durch nicht erfüllbare Werbeaussagen werden reduziert.']
]});
areas[3].items.push(
 ['marketingziele','Die Geschäftsführung setzt für eine neue Produktlinie ein Ziel „mehr Bekanntheit“, möchte aber später den Erfolg prüfen. Wie sollte das Ziel konkretisiert werden?','Zielgruppe, Messgröße, Ausgangswert, Zeitraum und angestrebte Veränderung festlegen.',['Nur die Zahl der Werbebeiträge als Bekanntheit messen.','Den Zielwert nach Ablauf der Kampagne auswählen.','Bekanntheit ohne definiertes Publikum vergleichen.'],'Ein operationalisiertes Marketingziel braucht Zielgruppe und messbares Kriterium.','Das Budget kann anhand einer überprüfbaren Wirkung statt bloßer Aktivität beurteilt werden.'],
 ['marketingforschung','Ein Wettbewerber veröffentlicht niedrige Preise, aber keine Informationen zu Lieferumfang und Service. Was sollte Vertrieb vor einem Preisvergleich klären?','Leistungsumfang, Mengen, Lieferbedingungen und Service der Angebote vergleichbar machen.',['Den veröffentlichten Einzelpreis als vollständigen Vergleich verwenden.','Eigene Serviceleistungen aus dem Angebot entfernen.','Wettbewerberpreis ungeprüft als Marktpreis für alle Kunden übernehmen.'],'Nur vergleichbare Leistungen erlauben eine sachgerechte Preisbewertung.','Unbegründete Preisnachlässe werden vermieden und Angebotsvorteile können eingeordnet werden.'],
 ['marktsegment','Ein Teil der Kunden kauft wegen dokumentierter Rückverfolgbarkeit, andere ausschließlich wegen kurzer Lieferzeit. Wie kann Vertrieb die Ansprache differenzieren?','Kunden nach ihren wichtigsten Kaufkriterien segmentieren und passende Nutzenargumente entwickeln.',['Allen Kunden denselben Vorteil hervorheben.','Segmente ausschließlich nach geografischer Entfernung bilden.','Die unterschiedlichen Kaufmotive als zufällige Einzelfälle behandeln.'],'Segmentierung nach Bedarf ermöglicht relevante Kommunikation und passende Leistungsbündel.','Vertrieb kann bessere Passung erreichen, ohne jedem Kunden dieselbe Leistung aufzudrängen.'],
 ['positionierung','Ein Betrieb wirbt mit „Premiumqualität“, obwohl Reklamationsdaten keine besondere Qualitätsposition belegen. Was sollte Marketing tun?','Aussage durch überprüfbare Leistungsmerkmale belegen oder realistisch neu formulieren.',['Die Aussage häufiger wiederholen, damit sie glaubwürdig wird.','Qualitätsdaten nicht mit Werbeaussagen verbinden.','Kundenreklamationen aus der internen Statistik entfernen.'],'Eine Positionierung sollte mit tatsächlich belegbarer Leistung übereinstimmen.','Das Unternehmen senkt Irreführungs- und Vertrauensrisiken und richtet Versprechen auf echte Stärken aus.'],
 ['marketingmix','Eine neue Zielgruppe kennt den Betrieb, aber Anfragen brechen an einem umständlichen Kontaktprozess ab. Welcher Marketingbereich sollte zuerst verbessert werden?','Distribution beziehungsweise Zugang zum Angebot und Vertriebsprozess überprüfen.',['Die Produktvorteile stärker kommunizieren und den Aufwand des Anfragewegs in einer späteren Vertriebsanalyse prüfen.','Das Kontaktformular verkürzen, auch wenn dadurch zunächst Angaben zur konkreten Angebotsqualifizierung fehlen.','Die Bekanntheit der Zielgruppe durch zusätzliche Werbung erhöhen und den bestehenden Anfrageweg zunächst beibehalten.'],'Marketing umfasst neben Bekanntheit auch Zugang und Vertriebsweg.','Interessenten können mit geringerem Aufwand in qualifizierte Anfragen übergehen.'],
 ['produktpolitik','Kunden fragen häufig nach unterschiedlichen technischen Varianten, die kleine Änderungen in der Fertigung erfordern. Welche Produktentscheidung ist sinnvoll?','Variantenbedarf, Fertigungsaufwand und Zahlungsbereitschaft systematisch prüfen.',['Jede gewünschte Variante ohne Standardisierung aufnehmen.','Alle Sonderwünsche pauschal ablehnen.','Entwicklungs- und Rüstaufwand im Produktangebot ausblenden.'],'Varianten können Nutzen schaffen, erhöhen aber Komplexität und Kosten.','Das Sortiment bleibt kundengerecht, ohne unkontrolliert Fertigungs- und Lagerkomplexität aufzubauen.'],
 ['preispolitik','Ein Angebot erzielt viele Zuschläge, aber der Betrieb kann die vereinbarten Termine nur mit teuren Überstunden einhalten. Was sollte die Preisprüfung ergänzen?','Kapazitäts- und Eilkosten in die Angebotskalkulation einbeziehen.',['Die Zuschlagsquote als ausreichenden Gewinnnachweis behandeln.','Überstunden unabhängig von Auftragsbeitrag als kostenlos ansehen.','Den Preis nach Annahme einseitig erhöhen.'],'Eine hohe Zuschlagsquote kann wirtschaftlich problematisch sein, wenn die Kalkulation den Kapazitätsaufwand verfehlt.','Angebote berücksichtigen stärker, ob Marge und Lieferfähigkeit gemeinsam tragfähig sind.'],
 ['vertriebsmanagement','Ein Mitarbeiter verspricht im Verkauf Sonderkonditionen, die intern nicht freigegeben wurden. Welche Prozessregel hilft?','Rabatt- und Angebotsbefugnisse mit klaren Schwellen und Freigabeschritten definieren.',['Jeden Rabatt nachträglich ohne Prüfung akzeptieren.','Vertriebsmitarbeitende ohne Befugnis über Preise entscheiden lassen.','Preisverhandlungen generell verbieten.'],'Definierte Spielräume beschleunigen Routinefälle und sichern Kontrolle bei größeren Abweichungen.','Marge und Kundenzusagen werden verlässlicher gesteuert.'],
 ['vertriebsmanagement','Die Pipeline enthält viele Angebote ohne nächsten Kontakttermin. Wie kann die Vertriebsleitung die Prognose verbessern?','Für jede Verkaufschance Status, erwarteten nächsten Schritt und Begründung der Wahrscheinlichkeit pflegen.',['Alle Chancen mit identischer Abschlusswahrscheinlichkeit ansetzen.','Angebote nach einer Woche automatisch als gewonnen markieren.','Nur verlorene Chancen dokumentieren.'],'Aktualisierte Phasen und nächste Aktivitäten erhöhen Nachverfolgbarkeit und Prognosegüte.','Kapazität wird eher für reale Chancen eingeplant und veraltete Angebote fallen auf.'],
 ['kundenbindung','Ein Stammkunde wechselt den Ansprechpartner und kennt die bisherigen Sondervereinbarungen nicht. Welche Maßnahme sichert die Beziehung?','Vereinbarungen und Kontaktverlauf dokumentieren und den neuen Ansprechpartner strukturiert einführen.',['Den Kunden auffordern, alle Absprachen erneut nachzuweisen.','Sondervereinbarungen unkontrolliert weiterführen.','Die Kundenhistorie aus Datenschutzgründen vollständig löschen.'],'Geregelte Dokumentation ermöglicht Kontinuität bei einem Ansprechpartnerwechsel.','Der Kunde erlebt eine konsistente Betreuung und der Betrieb vermeidet widersprüchliche Konditionen.'],
 ['kundenservice','Ein Auftrag verspätet sich; die Fertigung kennt den Grund, der Kunde wurde aber noch nicht informiert. Wie sollte der Vertrieb reagieren?','Belastbaren neuen Termin und Handlungsoptionen mit der Fertigung klären und den Kunden zeitnah informieren.',['Den ursprünglich zugesagten Termin weiter bestätigen.','Die Verzögerung erst nach Kundenbeschwerde mitteilen.','Ohne Klärung einen beliebigen Ersatztermin zusagen.'],'Frühzeitige und abgestimmte Kommunikation erhält Handlungsspielraum und Glaubwürdigkeit.','Kunden können eigene Abläufe anpassen und Eskalationen werden eher vermieden.'],
 ['absatzprognose','Ein einmaliger Großauftrag lässt den Monatsumsatz stark steigen. Wie sollte die Absatzplanung den Effekt behandeln?','Einmalauftrag gesondert ausweisen und wiederkehrenden Grundbedarf separat prognostizieren.',['Den Spitzenmonat als neue Norm hochrechnen.','Den Auftrag aus der Umsatzhistorie löschen.','Den Einmalauftrag als sichere Folgejahresnachfrage werten.'],'Sondereffekte dürfen nicht ungeprüft als dauerhafter Trend fortgeschrieben werden.','Kapazitäts- und Umsatzplanung bleiben realistischer für Folgeperioden.'],
 ['marketingbudget','Ein Unternehmen verteilt Werbebudget gleichmäßig auf alle Kanäle, obwohl nur wenige qualifizierte Leads entstehen. Was sollte es auswerten?','Kosten je qualifiziertem Kontakt und nachgelagerte Auftragsbeiträge pro Kanal vergleichen.',['Impressionen als alleinige Erfolgsgröße verwenden.','Alle Kanäle unabhängig vom Ergebnis weiter finanzieren.','Kampagnenkosten aus der Wirtschaftlichkeitsbetrachtung auslassen.'],'Kanalwirkung sollte an Zielgruppenpassung und wirtschaftlichem Folgeergebnis gemessen werden.','Budget kann auf wirksame Kanäle konzentriert und Streuverlust reduziert werden.'],
 ['distributionspolitik','Ein Kunde möchte seine Ware selbst abholen, statt den Spediteur zu nutzen. Was muss der Betrieb vor Zusage abstimmen?','Bereitstellung, Übergabezeitpunkt, Verpackung und vereinbarte Verantwortungsübergänge klären.',['Den Auftrag ohne geänderte Absprachen im Versandprozess lassen.','Abholkosten automatisch als zusätzlichen Umsatz buchen.','Ware ohne Abholnachweis aus dem Lagerbestand ausbuchen.'],'Ein geänderter Lieferweg benötigt klare logistische Abläufe und Dokumentation.','Übergabefehler und Missverständnisse über Lieferverantwortung werden reduziert.'],
 ['angebotsgestaltung','Ein Kunde möchte mehrere Leistungsvarianten vergleichen. Wie sollte das Angebot gestaltet werden?','Varianten mit vergleichbarem Leistungsumfang, Preis und Liefertermin strukturiert gegenüberstellen.',['Eine Variante detailliert und andere ohne Leistungsbeschreibung anbieten.','Zusatzoptionen in den Gesamtpreis mischen, ohne sie zu benennen.','Dem Kunden die interne Kalkulation statt eines Angebots senden.'],'Vergleichbare Varianten unterstützen eine informierte Kundenauswahl.','Entscheidung und spätere Auftragserfüllung werden klarer, Zusatzleistungen bleiben nachvollziehbar.'],
 ['preisverhandlung','Der Kunde schlägt eine längere Vertragslaufzeit gegen einen Preisnachlass vor. Welche Kalkulation ist erforderlich?','Mengen- oder Planungsvorteile gegen Preisbindung, Risiko und erwartete Kostenentwicklung rechnen.',['Die längere Laufzeit ohne Kostenprüfung als sicheren Vorteil ansehen.','Den Nachlass dauerhaft gewähren, ohne Mindestmengen festzulegen.','Preisrisiken durch einseitige Anpassung nach Vertragsschluss lösen.'],'Eine längere Bindung kann Planungsvorteile, aber auch Preis- und Flexibilitätsrisiken mitbringen.','Konditionen werden an belastbare Gegenleistungen und klare Vertragsbedingungen geknüpft.'],
 ['vertragsrecht','Ein Kunde möchte nach Auftragserteilung eine zusätzliche Prüfung und einen früheren Liefertermin. Was sollte Vertrieb tun?','Leistungsänderung, Machbarkeit, Mehrkosten und Terminwirkung abstimmen und dokumentieren.',['Zusatzleistung ohne Preis- oder Terminprüfung zusagen.','Nachträglich eine Gebühr ohne Vereinbarung berechnen.','Den ursprünglichen Auftrag als nichtig behandeln.'],'Nachträgliche Änderungen erfordern abgestimmte Leistungs- und Preisbedingungen.','Der Betrieb kann Zusatzwünsche erfüllen, ohne Umfang, Marge und Lieferplan unklar zu lassen.'],
 ['internationalisierung','Ein Auslandsinteressent verlangt ein Angebot mit Lieferung an einen neuen Zielort. Welche logistischen und kaufmännischen Punkte sind zu klären?','Transportweg, Kosten, Lieferbedingungen, Währung und Zahlungsrisiko prüfen.',['Inlandspreis und Inlandslieferzeit unverändert übernehmen.','Wechselkurs und Transportkosten als irrelevant behandeln.','Zielort erst nach Versand erfragen.'],'Neue Absatzgebiete können zusätzliche Kosten und Vertragsbedingungen auslösen.','Die Angebotsmarge und Lieferzusage berücksichtigen die tatsächliche Distanz und Abwicklung.'],
 ['interkulturelle_kommunikation','Ein Geschäftspartner signalisiert Zustimmung in einem Gespräch, bestätigt den Umfang aber nicht schriftlich. Was sollte das Vertriebsteam tun?','Gemeinsames Verständnis, offene Punkte und nächste Schritte schriftlich zusammenfassen und bestätigen lassen.',['Die Gesprächsreaktion als vollständige Vertragsannahme behandeln.','Die offenen Punkte nicht mehr ansprechen.','Den Umfang intern nach eigener Auslegung festlegen.'],'Zusammenfassung und Bestätigung reduzieren Interpretationsunterschiede.','Die Parteien können Missverständnisse über Leistung und Verbindlichkeit früh klären.'],
 ['crm','Kundenbeschwerden werden erfasst, aber nicht nach Produkt, Ursache oder Wiederholung ausgewertet. Welche CRM-Nutzung fehlt?','Beschwerdedaten strukturiert analysieren und Erkenntnisse an Produkt- und Prozessverantwortliche zurückführen.',['Einzelbeschwerden isoliert schließen.','Kundendaten nur für Werbeversand verwenden.','Wiederholungen wegen bereits erfolgter Lösung ignorieren.'],'CRM kann neben Vertrieb auch Muster und Verbesserungsbedarf sichtbar machen.','Produkt- und Prozessverbesserungen können auf wiederkehrenden Kundensignalen beruhen.'],
 ['absatzkontrolle','Eine Kampagne hat ihr Umsatzziel erreicht, aber durch hohe Rabatte einen deutlich geringeren Deckungsbeitrag erzielt. Wie ist der Erfolg zu bewerten?','Umsatzergebnis und Deckungsbeitrag gemeinsam mit Kampagnenkosten beurteilen.',['Zielerreichung beim Umsatz als vollständigen Erfolg werten.','Rabatte als zusätzlichen Absatz verbuchen.','Kampagnenkosten ignorieren, weil Umsatz einging.'],'Umsatz allein zeigt nicht, ob eine Kampagne wirtschaftlichen Beitrag leistet.','Marketing kann künftige Aktionen auf profitable Kunden und Konditionen ausrichten.'],
 ['sortimentspolitik','Ein Produkt verursacht viele Variantenwechsel und geringe Stückzahlen, wird aber in Kombination mit anderen Leistungen verkauft. Was sollte vor einer Streichung geprüft werden?','Direkter Beitrag, Verbundwirkung und Auswirkungen auf Kundenbeziehungen untersuchen.',['Nur die isolierte Stückzahl für die Entscheidung verwenden.','Verbundeffekte als grundsätzlich nicht messbar abtun.','Das Produkt ohne Kundenprüfung sofort auslisten.'],'Produkte können indirekten Nutzen oder Verbundumsatz erzeugen; dieser muss nachvollziehbar bewertet werden.','Sortimentsentscheidungen berücksichtigen tatsächliche Kunden- und Ergebniswirkungen.'],
 ['kommunikation','Ein Werbetext behauptet eine Zertifizierung, die für das konkrete Produkt nicht gilt. Was muss das Marketingteam tun?','Aussage korrigieren und Produktbezug sowie Nachweis vor Verwendung prüfen.',['Die Aussage wegen des Unternehmenszertifikats unverändert lassen.','Den Hinweis klein drucken und den falschen Eindruck beibehalten.','Die Zertifizierung als Marketingbegriff ohne Beleg behandeln.'],'Produktbezogene Werbeaussagen müssen sachlich belegt und nicht irreführend sein.','Der Betrieb senkt rechtliche und reputative Risiken durch korrekte Kommunikation.'],
 ['marketingcontrolling','Die Website erzeugt viele Anfragen, aber die meisten sind technisch nicht erfüllbar. Welche Kennzahl hilft die Kampagne gezielter zu bewerten?','Anteil qualifizierter, zum Leistungsprofil passender Leads messen.',['Nur Seitenaufrufe erhöhen.','Jede Anfrage als Verkaufschance zählen.','Unpassende Anfragen aus dem Bericht löschen.'],'Leadqualität misst die Passung zum Zielkunden und nicht nur Reichweite.','Marketing und Fertigung verschwenden weniger Aufwand auf nicht realisierbare Angebote.'],
 ['kundensegmentierung','Ein Kunde kauft selten, aber mit hoher Marge und geringer Sonderbetreuung; ein anderer bestellt häufig mit vielen Reklamationen. Wie sollte die Betreuung priorisiert werden?','Kundenwert und Betreuungsaufwand anhand geeigneter Kriterien differenziert analysieren.',['Betreuung ausschließlich nach Bestellhäufigkeit priorisieren.','Den Kunden mit Reklamationen automatisch kündigen.','Nur Umsatz ohne Kosten- und Zukunftssicht vergleichen.'],'Kundensegmentierung kann Ertrag, Aufwand und strategische Bedeutung berücksichtigen.','Service- und Vertriebsressourcen werden bewusster auf tragfähige Beziehungen verteilt.'],
 ['preisstrategie','Ein Kunde fordert einen Festpreis für ein Projekt mit unsicherem Materialverbrauch. Wie sollte das Angebot abgesichert werden?','Verbrauchsannahmen, Leistungsumfang und Umgang mit Änderungen klar vereinbaren.',['Puffer ohne Dokumentation in den Preis einrechnen.','Festpreis ohne Mengen- oder Änderungsgrenzen zusagen.','Mehrverbrauch nachträglich ohne vorherige Vereinbarung berechnen.'],'Klare Annahmen und Änderungsregeln verteilen Unsicherheit nachvollziehbar.','Preisrisiko aus Verbrauchsabweichungen wird besser steuerbar und der Kunde kennt den Angebotsumfang.']
);
areas.push({id:'hsq-fuehrung-zusammenarbeit',name:'Führung und Zusammenarbeit',paragraph:5,items:[
 ['kommunikation','Eine Schichtübergabe lässt offen, ob ein Auftrag bereits geprüft wurde. Welche Kommunikationsstruktur verhindert Missverständnisse?','Auftragsstatus, offene Prüfung, Verantwortlichen und nächsten Schritt standardisiert übergeben.',['Nur die Anwesenheit der Schicht protokollieren.','Unklare Punkte bis zum nächsten Fehler offenlassen.','Jede Schicht eigene Statusbegriffe verwenden lassen.'],'Eine strukturierte Übergabe vermittelt die für die Anschlussarbeit nötigen Informationen.','Doppelprüfungen und ungeprüfte Weiterbearbeitung werden seltener.'],
 ['kommunikation','Ein Mitarbeiter meldet einen Fehler; Ablauf und Ursache sind zunächst unklar. Welche erste Reaktion ermöglicht eine belastbare Ursachenklärung, ohne Verantwortung vorwegzunehmen?','Zunächst Beobachtungen und Abläufe erfragen und zwischen Ursache und Verantwortung unterscheiden.',['Die schriftliche Fehlerdokumentation als Ausgangspunkt nehmen und die Beschäftigten nur dann befragen, wenn die Einträge einander widersprechen.','Fehlerberichte vertraulich an die Führungskraft richten und die Ergebnisse der Ursachenanalyse später im Team teilen.','Die erste Schilderung als Arbeitshypothese verwenden und eine Prozessänderung nach kurzer Beobachtung im laufenden Betrieb testen.'],'Offene Fragen schaffen eine belastbare Grundlage für Ursachenanalyse statt vorschneller Schuldzuweisung.','Beschäftigte melden Risiken eher frühzeitig und Fehlerursachen lassen sich besser beheben.'],
 ['kooperation','Vertrieb und Fertigung streiten über die Zusage eines Eiltermins. Wie kann die Zusammenarbeit verbessert werden?','Gemeinsame Prioritätskriterien und Eskalationsweg für Eilaufträge vereinbaren.',['Den Konflikt allein dem Vertrieb überlassen.','Alle Kundenanfragen pauschal als dringend behandeln.','Die Produktionsplanung ohne Rückmeldung ändern.'],'Gemeinsame Regeln verbinden Kundenanforderung und reale Kapazität.','Eilaufträge werden transparenter priorisiert und weniger andere Zusagen gefährdet.'],
 ['mitarbeitergespraech','Ein Mitarbeiter erreicht seine Qualitätsziele, berichtet aber von Überlastung. Wie sollte ein Führungsgespräch geführt werden?','Leistung und Belastung konkret besprechen und gemeinsam mögliche Ursachen sowie Unterstützung klären.',['Die Zielerreichung als Beweis fehlender Belastung ansehen.','Überlastung pauschal als mangelnde Motivation werten.','Alle Aufgaben ohne Rücksprache neu verteilen.'],'Ein Gespräch soll Fakten, persönliche Wahrnehmung und mögliche Maßnahmen erfassen.','Belastungsrisiken können früher bearbeitet werden, ohne Leistung oder Gesundheit gegeneinander auszuspielen.'],
 ['mitarbeitergespraech','Eine neue Mitarbeiterin fragt selten nach Hilfe und macht dadurch vermeidbare Fehler. Welche Gesprächsführung ist hilfreich?','Konkrete Beobachtung ansprechen, Erwartungen an Rückfragen klären und Unterstützung anbieten.',['Die Person als ungeeignet abstempeln.','Fehler stillschweigend selbst korrigieren.','Nur die Fehlerzahl ohne Gespräch dokumentieren.'],'Konkretes Feedback und klare Hilfswege machen Erwartungen handhabbar.','Die Beschäftigte kann Unsicherheiten früher melden und Fehler besser vermeiden.'],
 ['feedback','Ein Teamleiter muss eine wiederholt verspätete Auftragsdokumentation ansprechen. Welche Rückmeldung ist am konstruktivsten?','Zeitnah konkrete Beispiele, betriebliche Folgen und erwartetes Verhalten benennen.',['Die Persönlichkeit des Mitarbeiters pauschal abwerten.','Die Rückmeldung vor dem gesamten Team als Strafe geben.','Nur andeuten, dass „es besser werden muss“.'],'Sachliches und beobachtbares Feedback erleichtert eine klare Veränderung.','Dokumentationsqualität und Zusammenarbeit können verbessert werden, ohne die Person herabzusetzen.'],
 ['motivation','Ein Team erhält regelmäßig neue Prioritäten, ohne zu erfahren, warum frühere Aufgaben gestoppt wurden. Was sollte Führung tun?','Zielkonflikte und Prioritätswechsel transparent erläutern und Auswirkungen gemeinsam abstimmen.',['Weitere Prioritätswechsel ohne Begründung einführen.','Beschäftigte für liegengebliebene Aufgaben verantwortlich machen.','Kommunikation auf Endergebnisse beschränken.'],'Nachvollziehbare Entscheidungen geben Orientierung und erhöhen die Akzeptanz von Änderungen.','Das Team richtet Arbeit weniger häufig auf überholte Ziele aus.'],
 ['konfliktmanagement','Nach einer fehlerhaften Übergabe beschuldigen sich zwei Fachkräfte gegenseitig; die Schichtprotokolle liegen vor. Die Führung will beide Sichtweisen hören, bevor sie den Prozess ändert. Welche Maßnahme stellt sicher, dass beide Beschäftigten ihre Darstellung einbringen?','Getrennte Sachverhalte und Erwartungen aufnehmen und anschließend einen gemeinsamen Klärungstermin strukturieren.',['Die Verantwortung zunächst der Person mit der letzten Übergabe zuordnen und Prozessdetails anschließend nacherheben.','Die Übergabeprotokolle getrennt prüfen und daraus eine neue Regel ableiten, bevor beide Fachkräfte ihre Sicht gemeinsam erläutern.','Die Zusammenarbeit vorübergehend auf getrennte Aufgaben verteilen und den Übergabeprozess parallel in einem moderierten Termin klären.'],'Eine strukturierte Klärung trennt Prozessprobleme von persönlichen Vorwürfen.','Übergaberegeln und Arbeitsbeziehungen können gezielt verbessert werden.'],
 ['konfliktmanagement','Ein Mitarbeiter widerspricht in einer Besprechung deutlich der geplanten Arbeitsfolge. Wie sollte die Führungskraft reagieren?','Einwand und Begründung anhören und anhand gemeinsamer Kriterien prüfen.',['Widerspruch als Illoyalität werten.','Die Besprechung sofort beenden.','Den Einwand ohne Prüfung übernehmen und Entscheidung vermeiden.'],'Sachlicher Widerspruch kann Risiken sichtbar machen; die Entscheidung braucht dennoch Kriterien.','Fehlende Informationen kommen früh ans Licht und Entscheidungen werden besser begründet.'],
 ['mitarbeiterfoerderung','Eine Beschäftigte bearbeitet Routineaufträge sicher und möchte mehr Verantwortung übernehmen. Welche Fördermaßnahme ist geeignet?','Eine klar begrenzte Zusatzaufgabe mit Befugnis, Ziel und regelmäßiger Rückmeldung übertragen.',['Verantwortung ohne Befugnis hinzufügen.','Entwicklung bis zur nächsten Beförderungsrunde vertagen.','Alle Aufgaben gleichzeitig übertragen.'],'Abgestufte Verantwortung schafft Lerngelegenheiten bei kontrollierbarem Risiko.','Kompetenz und Eigenständigkeit können wachsen, während Ergebnisse begleitet werden.'],
 ['mitarbeiterfoerderung','Ein Mitarbeiter zeigt Stärke in der Fehleranalyse, aber wenig Erfahrung mit Kundenkommunikation. Wie kann die Führungskraft seine Entwicklung planen?','Kompetenzprofil und Zielrolle abgleichen und passende Übungs- oder Lerngelegenheiten vereinbaren.',['Nur die vorhandene Stärke weiter nutzen und Entwicklung ignorieren.','Den Mitarbeiter ohne Vorbereitung allein Kundengespräche führen lassen.','Ein allgemeines Seminar ohne Lernziel buchen.'],'Entwicklung setzt bei der Lücke zwischen vorhandener Fähigkeit und künftigem Aufgabenbedarf an.','Der Betrieb kann interne Talente auf neue Rollen vorbereiten und Übergaben absichern.'],
 ['ausbildung','Ein Betrieb möchte erstmals ausbilden; die benannte Fachkraft hat Berufserfahrung, aber ihre persönliche und fachliche Eignung sowie Ausbildereignung wurden noch nicht geprüft. Was muss vor Ausbildungsbeginn geklärt werden?','Persönliche und fachliche Eignung sowie verantwortliche geeignete Ausbilder nach BBiG prüfen.',['Ausbildung beginnen und Eignung erst bei der ersten Prüfung kontrollieren.','Berufserfahrung als Auswahlkriterium nutzen und die erforderlichen persönlichen und fachlichen Nachweise vor der Bestellung prüfen.','Auszubildende im Rahmen des Ausbildungsplans produktiv mitarbeiten lassen und die Betreuungskapazität der zuständigen Ausbilderin in der Schichtplanung berücksichtigen.'],'Das BBiG verlangt persönliche und fachliche Eignung; ein Betrieb muss geeignete Ausbildungsverantwortung sicherstellen.','Ordnungsgemäße Betreuung wird vor Beginn geklärt und Ausbildungsqualität nicht dem Zufall überlassen.'],
 ['ausbildung','Eine geeignete Ausbilderin ist bestellt, doch ihre Abwesenheit lässt Auszubildende regelmäßig ohne Anleitung. Was sollte die Ausbildungsleitung organisieren?','Verlässliche Vertretung und verantwortliche Vermittlung der Ausbildungsinhalte sicherstellen.',['Ausbildungsinhalte während Abwesenheit vollständig aussetzen.','Azubis ohne Unterstützung allein mit Aufträgen betrauen.','Die Verantwortung auf Kunden übertragen.'],'Ausbildung erfordert wirksame Betreuung und Vermittlung, nicht nur eine formale Benennung.','Lernfortschritt bleibt kontinuierlich und der Betrieb nutzt Ausbildungszeit sachgerecht.'],
 ['ausbildung','Der Betrieb möchte einen Auszubildenden dauerhaft für monotone Hilfsarbeiten einsetzen. Welche Führungsentscheidung entspricht dem Ausbildungszweck?','Aufgaben am Ausbildungsplan und Lernzielen ausrichten und geeignete Ausbildungsinhalte vermitteln.',['Hilfsarbeit als vollständigen Ausbildungserfolg behandeln.','Lernziele dem kurzfristigen Produktionsbedarf unterordnen.','Ausbildung ausschließlich durch Selbststudium ersetzen.'],'Berufsausbildung soll berufliche Handlungsfähigkeit vermitteln und braucht planmäßige Lerninhalte.','Der Betrieb entwickelt qualifizierten Nachwuchs statt lediglich kurzfristige Arbeitskapazität zu nutzen.'],
 ['projektmoderation','Ein Projektteam verliert sich in Details und kommt nicht zu einer Entscheidung über die neue Lagerordnung. Was kann die Moderation tun?','Entscheidungsfrage, Kriterien, offene Punkte und Verantwortlichkeit sichtbar strukturieren.',['Die Diskussion ohne Zusammenfassung weiterlaufen lassen.','Die Moderation selbst ohne Kriterien entscheiden lassen.','Alle Details aus dem Protokoll entfernen.'],'Eine klare Moderationsstruktur führt von Sachfragen zu einer nachvollziehbaren Entscheidung.','Das Projektteam nutzt Zeit fokussierter und kann die beschlossene Lösung umsetzen.'],
 ['praesentation','Eine Führungskraft präsentiert neue Qualitätsziele vor Mitarbeitenden, die direkt betroffen sind. Wie sollte sie die Präsentation gestalten?','Ziele, betriebliche Gründe, erwartete Änderungen und Rückfragemöglichkeit verständlich darstellen.',['Nur Kennzahlen zeigen, ohne ihre Bedeutung zu erklären.','Einwände aus Zeitgründen vollständig ausschließen.','Die Präsentation an externe Investoren statt das Team richten.'],'Adressatengerechte Präsentation verbindet Information mit Bedeutung für die Arbeit.','Beschäftigte verstehen eher, was sich ändert und wo sie Fragen einbringen können.'],
 ['motivation','Ein Mitarbeiter erhält regelmäßig nur dann Rückmeldung, wenn etwas schiefgeht. Welche Führungsmaßnahme verbessert die Rückmeldekultur?','Auch gute Beiträge und Fortschritte konkret anerkennen und Entwicklungshinweise regelmäßig geben.',['Positives Feedback als unnötig streichen.','Anerkennung pauschal und ohne Bezug verteilen.','Nur jährliche Beurteilungen zulassen.'],'Ausgewogenes zeitnahes Feedback macht wirksames Verhalten sichtbar und unterstützt Lernen.','Engagement und Orientierung können steigen, während Verbesserungsthemen weiterhin angesprochen werden.'],
 ['kommunikation','Eine sicherheitskritische Anweisung erreicht per E-Mail nicht alle Beschäftigten der Schicht. Wie lässt sich bei einer sicherheitskritischen Anweisung die Kenntnisnahme je betroffener Person nachvollziehbar absichern?','Anweisung über Schichtkommunikation vermitteln, Verständnis abfragen und die Kenntnisnahme jeder betroffenen Person dokumentieren.',['Den Versandnachweis der E-Mail dokumentieren und Rückfragen nur bei Beschäftigten mit späteren Verständnisschwierigkeiten einholen.','Die Schichtleitung mit der Weitergabe beauftragen und deren Rückmeldung als ausreichenden Nachweis für das Team werten.','Die mündliche Übergabe durch die Schichtleitung nutzen und ihre Sammelbestätigung als Nachweis der individuellen Kenntnisnahme dokumentieren.'],'Kritische Informationen brauchen zugängliche Vermittlung und eine nachvollziehbare Verständnisprüfung.','Die Wahrscheinlichkeit sinkt, dass Beschäftigte mit unterschiedlichen Informationsständen arbeiten.'],
 ['kooperation','Ein neuer Arbeitsablauf betrifft drei Abteilungen, aber jede optimiert nur ihre eigenen Kennzahlen. Wie sollte die Leitung Zusammenarbeit fördern?','Gemeinsames Prozessergebnis und bereichsübergreifende Verantwortlichkeit vereinbaren.',['Lokale Kennzahlen unverändert als alleinige Ziele nutzen.','Eine Abteilung für alle Ergebnisse verantwortlich machen.','Bereichsübergreifende Abstimmung abschaffen.'],'Ein gemeinsames Ergebnis hilft, lokale Optimierung zulasten des Gesamtprozesses zu vermeiden.','Übergabezeiten und Gesamtqualität können verbessert werden, statt Probleme weiterzureichen.'],
 ['mitarbeitergespraech','Eine Mitarbeiterin fällt wiederholt durch kurzfristige Abwesenheiten auf; Gründe sind der Führungskraft unbekannt. Wie sollte das Gespräch beginnen?','Sachlich auf konkrete Auswirkungen eingehen und die Perspektive der Mitarbeiterin anhören.',['Gesundheitliche Ursachen unterstellen und bewerten.','Sofort Sanktionen ankündigen, ohne Sachverhalt.','Abwesenheiten im Team öffentlich diskutieren.'],'Ein sachliches Gespräch klärt betriebliche Auswirkungen und ermöglicht angemessene nächste Schritte.','Planungsprobleme werden angesprochen, ohne private Informationen oder Vermutungen unangemessen zu behandeln.'],
 ['konfliktmanagement','Ein Teamkonflikt wird durch widersprüchliche Rollenbeschreibungen verstärkt. Welche nachhaltige Maßnahme sollte der Führung folgen lassen?','Aufgaben, Entscheidungsrechte und Schnittstellen schriftlich klären.',['Nur die beteiligten Personen zum besseren Verhalten auffordern.','Rollenbeschreibungen weiter unklar lassen.','Die Aufgaben ohne Abstimmung doppelt vergeben.'],'Die strukturelle Ursache muss neben der zwischenmenschlichen Klärung behoben werden.','Wiederkehrende Konflikte durch Zuständigkeitslücken werden unwahrscheinlicher.'],
 ['mitarbeiterfoerderung','Ein Beschäftigter macht Fortschritte bei der Maschinenprogrammierung, benötigt aber noch Kontrolle bei komplexen Teilen. Wie sollte die Führung delegieren?','Aufgabenschwierigkeit schrittweise erhöhen und Kontrollpunkte passend zur Kompetenz vereinbaren.',['Alle komplexen Aufgaben sofort vollständig übertragen.','Weiterhin jede Routinehandlung kontrollieren.','Entwicklung trotz sichtbaren Fortschritts stoppen.'],'Delegation sollte Kompetenzstand und Risiko berücksichtigen und schrittweise angepasst werden.','Lernfortschritt wird gefördert, während Qualität bei anspruchsvollen Aufgaben gesichert bleibt.'],
 ['ausbildung','Eine Ausbilderin soll Inhalte digital vermitteln, ohne gleichzeitig mit dem Auszubildenden am selben Ort zu sein. Was muss nach BBiG für mobiles digitales Ausbilden besonders gewährleistet sein?','Geeignete Inhalte und Technik sowie gleichwertige Vermittlungsqualität mit Erreichbarkeit, Lernsteuerung und Kontrolle sicherstellen.',['Digitale Übertragung allein als ausreichende Vermittlung ansehen.','Lernfortschritt während digitaler Phasen nicht kontrollieren.','Jede Ausbildungsaufgabe unabhängig von Eignung digital durchführen.'],'§ 28 Abs. 2 BBiG knüpft mobiles digitales Ausbilden an geeignete Bedingungen und gleichwertige Qualität.','Digitale Flexibilität bleibt mit erreichbarer Betreuung und überprüfbarem Lernfortschritt verbunden.'],
 ['projektmoderation','In einer Projektbesprechung schweigen Mitarbeitende, obwohl sie später Bedenken äußern. Welche Moderation kann Beteiligung verbessern?','Runde gezielter Beteiligung, stille Ideensammlung oder strukturierte Rückfragen anbieten.',['Bedenken nur von den ranghöchsten Personen einholen.','Schweigen als einstimmige Zustimmung protokollieren.','Kritische Beiträge unmittelbar bewerten und beenden.'],'Niedrigschwellige Beteiligungsformen können bislang unausgesprochene Informationen sichtbar machen.','Projektrisiken und Umsetzungswiderstände werden früher erkennbar.']
]});
areas[4].items.push(
 ['kooperation','Einkauf und Qualitätssicherung können sich nicht einigen, ob eine Charge freigegeben werden soll. Welche Zusammenarbeit ist zielführend?','Prüfkriterien, Befund und Risikofolgen gemeinsam anhand der vereinbarten Qualitätsanforderung bewerten.',['Die Entscheidung allein nach Liefertermin treffen.','Eine Abteilung ohne Prüfung überstimmen lassen.','Die Charge freigeben, damit der Konflikt endet.'],'Fachbereiche müssen anhand gemeinsamer Kriterien zu einer nachvollziehbaren Entscheidung kommen.','Die Freigabe schützt Qualität und Lieferfähigkeit, statt einen Zielkonflikt zu verdecken.'],
 ['mitarbeitergespraech','Eine Führungskraft möchte mit einem Beschäftigten über eine neue Aufgabenverteilung sprechen. Wie sollte sie das Gespräch vorbereiten?','Ziel, relevante Fakten, Gesprächsfragen und mögliche Unterstützungsbedarfe festlegen.',['Die endgültige Entscheidung verbergen und nur Kritik sammeln.','Gespräch ohne konkreten Anlass ansetzen.','Die neue Aufgabenverteilung bereits als unumstößlich darstellen.'],'Vorbereitung ermöglicht ein fokussiertes Gespräch und lässt Raum, Auswirkungen der Änderung zu verstehen.','Aufgabenwechsel werden realistischer geplant und Akzeptanzhürden werden früh erkennbar.'],
 ['feedback','Nach einer Verbesserungsidee fällt die Umsetzung im Alltag schwer. Welches Feedback unterstützt Lernen?','Beobachtete Umsetzung und Hindernisse konkret besprechen und nächsten Versuch vereinbaren.',['Nur die ursprüngliche Idee bewerten, ohne Umsetzung zu betrachten.','Misserfolg als mangelndes Engagement bezeichnen.','Die Idee ohne Rückmeldung verwerfen.'],'Feedback sollte Verhalten, Rahmenbedingungen und nächste Lernschritte verbinden.','Verbesserungsarbeit kann angepasst werden statt nach dem ersten Hindernis zu enden.'],
 ['motivation','Ein Team empfindet die Zielvorgaben als unerreichbar, weil es bei deren Festlegung nicht beteiligt war. Was ist eine angemessene Führungsreaktion?','Zielannahmen und verfügbare Ressourcen offen prüfen und Mitarbeitende an der Umsetzungsplanung beteiligen.',['Das Ziel unverändert wiederholen und Zweifel untersagen.','Ziele ohne Rücksicht auf Strategie vollständig aufgeben.','Druck erhöhen, ohne Hindernisse zu analysieren.'],'Beteiligung und transparente Machbarkeitsprüfung können Motivation und Zielklarheit verbessern.','Die Leitung erhält realistischere Umsetzungspläne und erkennt Ressourcenlücken.'],
 ['konfliktmanagement','Ein Konflikt über Schichttausch eskaliert, weil beide Beschäftigten unterschiedliche Regeln annehmen. Wie sollte die Führung vorgehen?','Bestehende Regeln und individuelle Interessen klären und eine transparente Lösung für den konkreten Fall suchen.',['Einen Tausch allein nach persönlicher Sympathie genehmigen.','Die Regeln nach dem Konflikt rückwirkend ändern.','Beide Beschäftigte ohne Anhörung ablehnen.'],'Fakten und Interessen müssen von Vermutungen getrennt werden; Regeln geben einen fairen Rahmen.','Eine Lösung wird nachvollziehbarer und künftige Schichttauschkonflikte können durch klare Regeln sinken.'],
 ['mitarbeiterfoerderung','Eine Fachkraft soll künftig Qualitätsprüfungen koordinieren, kennt aber die Moderation von Ursachenbesprechungen kaum. Was ist eine passende Entwicklung?','Moderationskompetenz schrittweise durch Übung, Begleitung und Reflexion aufbauen.',['Die Person ohne Vorbereitung sofort allein mit Konflikten betrauen.','Die neue Rolle dauerhaft an eine andere Person vergeben.','Nur fachliche Prüfschritte schulen und Kommunikation auslassen.'],'Die Aufgabe verlangt fachliche und kommunikative Fähigkeiten; gezielte Entwicklung bereitet darauf vor.','Ursachenbesprechungen werden strukturierter und die neue Rolle tragfähiger.'],
 ['ausbildung','Ein Betrieb hat eine fachlich qualifizierte Person, aber ihre persönliche Eignung als Ausbilder ist ungeklärt. Was verlangt das BBiG grundsätzlich?','Auszubildende darf nur ausbilden, wer persönlich und fachlich geeignet ist.',['Fachliche Qualifikation allein genügt in jedem Fall.','Persönliche Eignung ist nur bei externen Ausbildern relevant.','Die Eignung kann ohne Prüfung durch Dienstalter ersetzt werden.'],'§ 28 Abs. 1 BBiG verlangt persönliche und fachliche Eignung; Details sind für den konkreten Fall zu prüfen.','Der Betrieb klärt die erforderlichen Voraussetzungen, bevor er Ausbildungsverantwortung überträgt.'],
 ['kommunikation','Eine Arbeitsanweisung enthält Fachbegriffe, die neue Beschäftigte nicht verstehen. Was ist eine geeignete Führungsmaßnahme?','Anweisung adressatengerecht erklären und Verständnis durch Rückfragen oder Demonstration prüfen.',['Die Anweisung unverändert wiederholen und fehlendes Verständnis als Unaufmerksamkeit bewerten.','Nur erfahrene Mitarbeitende informieren.','Fachbegriffe aus dem Dokument löschen, ohne die Inhalte zu prüfen.'],'Verständliche Kommunikation und Rückversicherung sichern die Umsetzung im Arbeitsalltag.','Fehler aus missverstandenen Vorgaben können abnehmen.'],
 ['kooperation','Ein Team erreicht das Produktionsziel, aber auf Kosten häufiger Übergabefehler an die nächste Schicht. Welche Zusammenarbeit sollte gestärkt werden?','Gemeinsame Qualitäts- und Übergabeziele über Schichtgrenzen hinweg vereinbaren.',['Nur die Menge der einzelnen Schicht weiter belohnen.','Übergabefehler der Folgeschicht zurechnen.','Schichtübergaben zeitlich kürzen, ohne Inhalt zu prüfen.'],'Gemeinsame Prozessverantwortung reduziert lokale Zieloptimierung zulasten des Gesamtbetriebs.','Qualität und Anschlussfähigkeit werden neben der Schichtleistung sichtbar.'],
 ['mitarbeitergespraech','Eine Beschäftigte zeigt gute Fachleistung, möchte aber ihre Arbeitszeit künftig anders organisieren. Wie sollte die Führungskraft das Anliegen behandeln?','Betriebliche Anforderungen und individuelle Möglichkeiten sachlich prüfen und Optionen besprechen.',['Den Wunsch allein wegen abweichender Routine ablehnen.','Eine Zusage ohne Prüfung der Schichtabdeckung erteilen.','Die persönliche Situation vor dem Team diskutieren.'],'Ein Gespräch soll berechtigte Bedürfnisse und betriebliche Rahmenbedingungen gegeneinander abwägen.','Mögliche Lösungen werden gefunden, ohne die Versorgung oder Privatsphäre zu übergehen.'],
 ['konfliktmanagement','Ein Mitarbeiter nimmt häufig Aufgaben eines Kollegen an sich und beide fühlen sich dadurch behindert. Welche Konfliktlösung ist geeignet?','Rollen und gewünschte Zusammenarbeit klären und Verantwortungsgrenzen vereinbaren.',['Die Initiative pauschal als Fehlverhalten sanktionieren.','Beide ohne Aufgabenklärung weiterarbeiten lassen.','Die Aufgaben dauerhaft doppelt vergeben.'],'Der Konflikt kann durch unklare Grenzen entstehen und braucht eine gemeinsame Rollenklärung.','Doppelarbeit und Frustration lassen sich reduzieren.'],
 ['mitarbeiterfoerderung','Eine Mitarbeiterin möchte sich fachlich weiterbilden, die Geschäftsführung benötigt aber kurzfristig ihre volle Einsatzzeit. Wie sollte entschieden werden?','Lernbedarf, betriebliche Priorität und alternative Zeitplanung transparent abwägen.',['Weiterbildung grundsätzlich auf unbestimmte Zeit verschieben.','Arbeitszeit ohne Abstimmung reduzieren.','Die Mitarbeiterin zur privaten Finanzierung und Durchführung verpflichten.'],'Personalentwicklung ist mit Kapazitätsplanung abzustimmen und braucht klare Rahmenbedingungen.','Kompetenzaufbau kann geplant werden, ohne kurzfristige Produktionsanforderungen zu übersehen.'],
 ['projektmoderation','Eine Besprechung mit mehreren Fachbereichen endet mit offenen Meinungsverschiedenheiten, obwohl keine Entscheidung getroffen werden muss. Was sollte die Moderation festhalten?','Gemeinsame Fakten, abweichende Positionen, offene Prüfaufgaben und nächste Abstimmung dokumentieren.',['Einstimmigkeit vortäuschen.','Nur die Mehrheitsmeinung protokollieren.','Die offenen Fragen ohne Verantwortliche belassen.'],'Dokumentation kann Unterschiede erhalten und dennoch konkrete nächste Schritte ermöglichen.','Das Projekt kommt voran, ohne ungeklärte Annahmen als Beschluss auszugeben.'],
 ['praesentation','Eine Führungskraft muss der Geschäftsleitung eine Weiterbildungsmaßnahme vorschlagen. Was macht die Präsentation entscheidungsfähig?','Bedarf, Zielgruppe, erwarteter Nutzen, Aufwand und Erfolgskontrolle knapp darstellen.',['Nur den Kurstitel und Anbieter nennen.','Kosten auslassen, damit die Zustimmung wahrscheinlicher ist.','Die Schulung als garantiert wirksam darstellen.'],'Entscheidungsrelevante Informationen erlauben eine sachgerechte Abwägung.','Das Unternehmen kann Weiterbildungsbudget an nachvollziehbare Kompetenzziele binden.'],
 ['ausbildung','Der Betrieb möchte einem erfahrenen Nicht-Ausbilder eine Teilaufgabe in der Ausbildung übertragen. Unter welcher Bedingung kann Mitwirkung nach BBiG erfolgen?','Unter Verantwortung des Ausbilders und bei erforderlichen beruflichen Fähigkeiten sowie persönlicher Eignung.',['Eigenständige Ausbildungsleitung ohne geeignete Ausbilderbestellung.','Allein aufgrund langer Betriebszugehörigkeit.','Ohne Prüfung, welche Ausbildungsinhalte vermittelt werden.'],'§ 28 Abs. 3 BBiG erlaubt Mitwirkung unter Verantwortung des Ausbilders bei den genannten Voraussetzungen.','Fachwissen kann genutzt werden und die verantwortliche Ausbildungssteuerung bleibt klar.'],
 ['kommunikation','Eine Führungskraft kündigt eine Prozessänderung erst am ersten Umsetzungstag an. Welche Kommunikationsplanung wäre besser gewesen?','Betroffene frühzeitig informieren, Gründe und Ablauf erläutern und Rückfragen ermöglichen.',['Änderungen grundsätzlich erst bei Start mitteilen.','Nur die Dokumentation aktualisieren, ohne Mitarbeitende zu informieren.','Information ausschließlich an die Geschäftsleitung geben.'],'Vorlauf ermöglicht Verständnis, Vorbereitung und Erkennen praktischer Hindernisse.','Anlaufstörungen und Widerstand aus überraschender Umsetzung können sinken.'],
 ['motivation','Mitarbeitende schlagen wiederholt Verbesserungen vor, erhalten aber nie Rückmeldung. Was sollte die Leitung einführen?','Ideenstatus, Bewertung und Entscheidung transparent rückmelden.',['Vorschläge ohne Antwort archivieren.','Nur umgesetzte Ideen rückmelden.','Alle Vorschläge automatisch umsetzen.'],'Rückmeldung zeigt, dass Beiträge geprüft werden, ohne jede Idee ungeprüft zu übernehmen.','Beteiligung bleibt glaubwürdig und die Leitung behält eine kontrollierte Auswahl.'],
 ['kooperation','Ein Projektteam aus Einkauf, Produktion und Vertrieb hat keine gemeinsame Definition für „lieferfähig“. Was sollte es tun?','Begriffe und Messkriterien für Verfügbarkeit und Termin gemeinsam festlegen.',['Jede Abteilung ihre eigene Definition weiterverwenden lassen.','Die Kennzahl durch eine allgemeine Zufriedenheitsfrage ersetzen.','Lieferfähigkeit nur aus Vertriebssicht beurteilen.'],'Gemeinsame Definitionen sind Voraussetzung für abgestimmte Entscheidungen.','Berichte und Prioritäten beruhen auf derselben operativen Bedeutung.'],
 ['mitarbeitergespraech','Ein Beschäftigter lehnt eine neue Aufgabe ab und nennt fehlende Einweisung als Grund. Was ist eine angemessene Reaktion?','Anforderung und Qualifikationsstand prüfen und notwendige Einweisung oder Anpassung besprechen.',['Ablehnung sofort als Disziplinarproblem behandeln.','Aufgabe ohne Einweisung zuweisen.','Die neue Aufgabe ohne weitere Klärung dauerhaft streichen.'],'Die Führung muss klären, ob Unsicherheit, Qualifikationsbedarf oder andere Gründe vorliegen.','Arbeitsfähigkeit und Sicherheit können durch gezielte Unterstützung verbessert werden.'],
 ['konfliktmanagement','Ein Konflikt zwischen Meister und Auszubildendem betrifft widersprüchliche Rückmeldungen zu einer Arbeit. Welche Lösung hilft?','Arbeitsstandard und Feedback abstimmen und dem Auszubildenden eine einheitliche Ansprechstruktur geben.',['Den Auszubildenden entscheiden lassen, welcher Meister recht hat.','Kritik an Lernenden im Team öffentlich austragen.','Widersprüche ignorieren.'],'Einheitliche Anforderungen sind wichtig für Lernen und verlässliche Ausführung.','Fehler aus widersprüchlicher Anleitung werden reduziert und Ausbildungsqualität steigt.'],
 ['mitarbeiterfoerderung','Die Nachfolge für eine Schlüsselrolle ist ungeklärt. Wie kann Personalentwicklung darauf reagieren?','Kompetenzanforderungen definieren, mögliche Kandidaten entwickeln und Wissenstransfer planen.',['Die Rolle bis zum Ausfall unbesetzt lassen.','Eine Person ohne Entwicklung sofort festlegen.','Nur den aktuellen Stelleninhaber stärker belasten.'],'Nachfolgeplanung verbindet künftigen Bedarf mit schrittweisem Kompetenzaufbau.','Betriebswissen und Führungsfähigkeit bleiben bei Wechseln besser verfügbar.'],
 ['ausbildung','Eine Ausbildungsstätte verfügt nicht über erforderliche Ausstattung für wesentliche Inhalte. Was sollte der Betrieb prüfen?','Eignung der Ausbildungsstätte und mögliche geeignete Ausbildungsverbünde oder Ergänzungen klären.',['Fehlende Inhalte durch reine Produktivarbeit ersetzen.','Ausstattungsmängel nicht dokumentieren.','Auszubildende selbst für externe Lernorte verantwortlich machen.'],'BBiG § 27 behandelt die Eignung der Ausbildungsstätte; notwendige Inhalte müssen vermittelt werden.','Der Betrieb kann Ausbildungsqualität und erforderliche Lernbedingungen vorab sicherstellen.'],
 ['projektmoderation','Ein Projektteam diskutiert über eine Veränderung, aber niemand kennt den Entscheidungstermin. Welche Moderationsmaßnahme ist sinnvoll?','Entscheidungsbedarf, Frist und benötigte Informationen zu Beginn festlegen.',['Die Diskussion offen verlängern.','Erst nach Fristablauf den Entscheidungsbedarf feststellen.','Alle Fachfragen ohne Priorität sammeln.'],'Ein klarer Entscheidungsrahmen strukturiert die Zusammenarbeit und Informationsbeschaffung.','Das Team kann rechtzeitig Ergebnisse liefern und Folgearbeiten planen.'],
 ['praesentation','Eine Fachkraft präsentiert technische Kennzahlen vor nichttechnischen Führungskräften. Wie sollte sie die Wirkung verständlich machen?','Kennzahl, Bezugsgröße, Trend und betriebliche Bedeutung in Alltagssprache erläutern.',['Nur Formeln zeigen und Interpretationen auslassen.','Vergleichswerte ohne Quelle präsentieren.','Schwierige Fragen durch technische Abkürzungen vermeiden.'],'Adressatengerechte Darstellung übersetzt Daten in entscheidungsrelevante Aussagen.','Führung kann Auswirkungen und Handlungsoptionen besser beurteilen.'],
 ['kommunikation','Eine kritische Anweisung muss an eine Schicht mit unterschiedlichen Sprachkenntnissen vermittelt werden. Welche Maßnahme ist angemessen?','Verständliche Sprache und geeignete Visualisierung nutzen und Verständnis praktisch rückbestätigen.',['Nur eine schriftliche Nachricht in komplexer Fachsprache versenden.','Verständnis anhand von Nicken annehmen.','Anweisungen aus Zeitgründen nicht übersetzen oder erklären.'],'Anpassung der Vermittlung unterstützt ein gemeinsames Verständnis, ohne den Inhalt zu verändern.','Umsetzungsfehler und Sicherheitsmissverständnisse werden weniger wahrscheinlich.']
);
areas[4].items.push(['mitarbeiterfoerderung','Eine Beschäftigte wird als Mentorin für eine neue Kollegin vorgeschlagen, obwohl sie selbst mit hoher Auslastung arbeitet. Was sollte die Führung vor der Zusage abstimmen?','Zeitbudget, Mentoringziel, Zuständigkeit und notwendige Entlastung gemeinsam festlegen.',['Zusatzaufgabe ohne Zeitfreigabe übertragen.','Mentoring allein nach Betriebszugehörigkeit vergeben.','Einarbeitung der neuen Kollegin vollständig der Mentorin überlassen.'],'Mentoring braucht klare Erwartungen und realistische Kapazität, damit Unterstützung tatsächlich stattfinden kann.','Die neue Kollegin erhält verlässliche Begleitung, während Überlastung und Qualitätsrisiken für die Mentorin begrenzt werden.']);
areas.forEach((area) => { if (area.items.length > 50) area.items = area.items.slice(0, 50); });

