function splitPrompt(text) {
  const re = /\b(Welche|Welcher|Welches|Was|Wie|Wodurch|Warum|Wozu|Unter welcher|Unter welchen|In welcher|Welche der folgenden)\b[^?]*\?/g;
  const matches = [...text.matchAll(re)];
  const match = matches.at(-1);
  if (!match || match.index < 18) throw new Error('Could not split case from question: ' + text);
  const scenario = text.slice(0, match.index).trim().replace(/[ ,;:]+$/, '');
  const question = text.slice(match.index).trim();
  if (scenario.length < 25 || question.length < 5) throw new Error('Insufficient scenario/question: ' + text);
  return { scenario, question };
}
